#[derive(Debug, Clone, Deserialize, JsonSchema)]
pub struct ChatId(
    #[schemars(
        description = "JSON string Telegram peer reference. Quote numeric IDs, including -100 channel/supergroup IDs; integers are rejected. Accepted: @username, username, positive user ID, negative basic-group ID, or an existing authenticated-account dialog ID."
    )]
    String,
);

#[derive(Debug, Clone, Deserialize, JsonSchema)]
pub struct UserRef(
    #[schemars(description = "Telegram user reference: @username, username, or positive user id")]
    String,
);

