#[derive(Debug, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
struct GetPrivacyRulesArgs {
    key: PrivacyKey,
}

#[derive(Debug, Clone, Copy, Deserialize, JsonSchema, PartialEq, Eq, Hash)]
#[serde(rename_all = "snake_case")]
enum PrivacyRuleKind {
    AllowContacts,
    AllowAll,
    AllowUsers,
    DisallowContacts,
    DisallowAll,
    DisallowUsers,
    AllowChatParticipants,
    DisallowChatParticipants,
    AllowCloseFriends,
    AllowPremium,
    AllowBots,
    DisallowBots,
}

impl PrivacyRuleKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::AllowContacts => "allow_contacts",
            Self::AllowAll => "allow_all",
            Self::AllowUsers => "allow_users",
            Self::DisallowContacts => "disallow_contacts",
            Self::DisallowAll => "disallow_all",
            Self::DisallowUsers => "disallow_users",
            Self::AllowChatParticipants => "allow_chat_participants",
            Self::DisallowChatParticipants => "disallow_chat_participants",
            Self::AllowCloseFriends => "allow_close_friends",
            Self::AllowPremium => "allow_premium",
            Self::AllowBots => "allow_bots",
            Self::DisallowBots => "disallow_bots",
        }
    }

    fn uses_users(self) -> bool {
        matches!(self, Self::AllowUsers | Self::DisallowUsers)
    }

    fn uses_chats(self) -> bool {
        matches!(self, Self::AllowChatParticipants | Self::DisallowChatParticipants)
    }

    fn is_terminal(self) -> bool {
        matches!(self, Self::AllowAll | Self::DisallowAll)
    }
}

