    /// Poll Telegram's global updates difference from an exact pts/qts/date cursor.
    #[tool(annotations(
        title = "Poll Telegram global updates",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn get_updates(
        &self,
        Parameters(args): Parameters<GetUpdatesArgs>,
    ) -> Result<
        Json<ToolOutcome<UpdatesDifferenceSummary>>,
        Json<ToolOutcome<UpdatesDifferenceSummary>>,
    > {
        if args.pts < 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_updates.pts must be nonnegative",
            ))));
        }
        if args.qts < 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_updates.qts must be nonnegative",
            ))));
        }
        if args.date <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_updates.date must be positive",
            ))));
        }
        let pts_limit = validate_limit(
            args.pts_limit.unwrap_or(DEFAULT_UPDATES_PTS_LIMIT),
            MAX_UPDATES_LIMIT,
            "get_updates.pts_limit",
        )
        .and_then(|limit| {
            i32::try_from(limit).map_err(|_| {
                ToolFailure::invalid_argument("get_updates.pts_limit exceeds Telegram i32")
            })
        })
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let pts_total_limit = validate_limit(
            args.pts_total_limit.unwrap_or(DEFAULT_UPDATES_PTS_TOTAL_LIMIT),
            MAX_UPDATES_LIMIT,
            "get_updates.pts_total_limit",
        )
        .and_then(|limit| {
            i32::try_from(limit).map_err(|_| {
                ToolFailure::invalid_argument("get_updates.pts_total_limit exceeds Telegram i32")
            })
        })
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let qts_limit = args
            .qts_limit
            .map(|limit| {
                validate_limit(limit, MAX_UPDATES_LIMIT, "get_updates.qts_limit").and_then(
                    |limit| {
                        i32::try_from(limit).map_err(|_| {
                            ToolFailure::invalid_argument(
                                "get_updates.qts_limit exceeds Telegram i32",
                            )
                        })
                    },
                )
            })
            .transpose()
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let difference = self
            .backend
            .get_updates_difference(UpdatesDifferenceRequest {
                session_path: None,
                pts: args.pts,
                qts: args.qts,
                date: args.date,
                pts_limit: Some(pts_limit),
                pts_total_limit: Some(pts_total_limit),
                qts_limit,
            })
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        Ok(Json(ToolOutcome::success(difference)))
    }

    /// Poll one Telegram channel or supergroup from an exact channel pts cursor.
    #[tool(annotations(
        title = "Poll Telegram channel updates",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn get_channel_updates(
        &self,
        Parameters(args): Parameters<GetChannelUpdatesArgs>,
    ) -> Result<
        Json<ToolOutcome<ChannelUpdatesDifferenceSummary>>,
        Json<ToolOutcome<ChannelUpdatesDifferenceSummary>>,
    > {
        validate_chat_id(&args.chat_id, "get_channel_updates")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.pts < 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_channel_updates.pts must be nonnegative",
            ))));
        }
        let limit = args.limit.unwrap_or(DEFAULT_CHANNEL_UPDATES_LIMIT);
        if !(MIN_CHANNEL_UPDATES_LIMIT..=MAX_CHANNEL_UPDATES_LIMIT).contains(&limit) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "get_channel_updates.limit must be between {MIN_CHANNEL_UPDATES_LIMIT} and {MAX_CHANNEL_UPDATES_LIMIT} for user accounts"
            )))));
        }
        let limit = i32::try_from(limit).map_err(|_| {
            Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_channel_updates.limit exceeds Telegram i32",
            )))
        })?;
        let difference = self
            .backend
            .get_channel_updates(ChannelUpdatesRequest {
                session_path: None,
                chat_id: args.chat_id.0,
                pts: args.pts,
                limit,
                force: args.force,
            })
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        Ok(Json(ToolOutcome::success(difference)))
    }

