    /// Read one filtered, paginated Telegram Stars transaction page for an exact wallet peer.
    #[tool(annotations(
        title = "List Telegram Stars transactions",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn get_stars_transactions(
        &self,
        Parameters(args): Parameters<GetStarsTransactionsArgs>,
    ) -> Result<Json<ToolOutcome<StarsStatusPage>>, Json<ToolOutcome<StarsStatusPage>>> {
        validate_stars_peer(&args.peer, "get_stars_transactions")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.inbound && args.outbound {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_stars_transactions.inbound and outbound are mutually exclusive",
            ))));
        }
        if let Some(subscription_id) = args.subscription_id.as_deref() {
            validate_nonempty_utf16(
                subscription_id,
                MAX_STARS_SUBSCRIPTION_ID_UTF16,
                "get_stars_transactions.subscription_id",
            )
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        }
        let offset = args.offset.unwrap_or_default();
        validate_optional_utf16(&offset, MAX_STARS_OFFSET_UTF16, "get_stars_transactions.offset")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let limit = validate_limit(
            args.limit.unwrap_or(DEFAULT_STARS_TRANSACTIONS_LIMIT),
            MAX_STARS_TRANSACTIONS_LIMIT,
            "get_stars_transactions.limit",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let limit = i32::try_from(limit).map_err(|_| {
            Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_stars_transactions.limit exceeds Telegram's signed 32-bit range",
            )))
        })?;
        let page = self
            .backend
            .get_stars_transactions(
                None,
                &args.peer.0,
                args.inbound,
                args.outbound,
                args.ascending,
                args.subscription_id.as_deref(),
                &offset,
                limit,
            )
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        Ok(Json(ToolOutcome::success(page)))
    }

