    async fn get_saved_star_gifts(
        &self,
        Parameters(args): Parameters<GetSavedStarGiftsArgs>,
    ) -> Result<Json<ToolOutcome<SavedStarGiftsPage>>, Json<ToolOutcome<SavedStarGiftsPage>>> {
        validate_stars_peer(&args.chat_id, "get_saved_star_gifts")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let offset = args.offset.unwrap_or_default();
        validate_optional_utf16(&offset, MAX_STARS_OFFSET_UTF16, "get_saved_star_gifts.offset")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let limit = validate_limit(
            args.limit.unwrap_or(DEFAULT_SAVED_STAR_GIFTS_LIMIT),
            MAX_SAVED_STAR_GIFTS_LIMIT,
            "get_saved_star_gifts.limit",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let limit = i32::try_from(limit).map_err(|_| {
            Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_saved_star_gifts.limit exceeds Telegram's signed 32-bit range",
            )))
        })?;
        if args.collection_id.is_some_and(|collection_id| collection_id <= 0) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_saved_star_gifts.collection_id must be positive",
            ))));
        }
        let page = self
            .backend
            .get_saved_star_gifts(SavedStarGiftsRequest {
                session_path: None,
                peer_ref: args.chat_id.0,
                exclude_unsaved: args.exclude_unsaved,
                exclude_saved: args.exclude_saved,
                exclude_unlimited: args.exclude_unlimited,
                exclude_limited: args.exclude_limited,
                exclude_unique: args.exclude_unique,
                sort_by_value: args.sort_by_value,
                exclude_upgradable: args.exclude_upgradable,
                exclude_unupgradable: args.exclude_unupgradable,
                peer_color_available: args.peer_color_available,
                exclude_hosted: args.exclude_hosted,
                collection_id: args.collection_id,
                offset,
                limit,
            })
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        Ok(Json(ToolOutcome::success(page)))
    }

