    /// Get one exact Telegram message by chat and message ID.
    #[tool(annotations(
        title = "Get Telegram message",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn get_message(
        &self,
        Parameters(args): Parameters<GetMessageArgs>,
    ) -> Result<Json<ToolOutcome<GetMessageResult>>, Json<ToolOutcome<GetMessageResult>>> {
        validate_chat_id(&args.chat_id, "get_message")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_id <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_message.message_id must be positive",
            ))));
        }
        let cache_context = self.cache_account_context().await.ok();
        let session_path = cache_context.as_ref().map(|(_, path, _)| path.clone());
        let passive_cache_state = if let Some((account, path, generation)) = &cache_context {
            self.passive_cache_chat_state(account.user_id, *generation, path, &args.chat_id.0).await
        } else {
            None
        };
        let provider_chat_id = passive_cache_state
            .as_ref()
            .map(|(canonical_chat_id, _)| canonical_chat_id.as_str())
            .unwrap_or(&args.chat_id.0);
        let message = self
            .backend
            .get_message(session_path, provider_chat_id, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "MESSAGE_NOT_FOUND",
                    format!("message {} was not found in {}", args.message_id, args.chat_id.0),
                    false,
                )))
            })?;
        if let (Some((account, _, generation)), Some((canonical_chat_id, chat_revision))) =
            (cache_context, passive_cache_state)
        {
            self.cache_live_messages_best_effort(
                account.user_id,
                generation,
                &canonical_chat_id,
                chat_revision,
                std::slice::from_ref(&message),
                MessageSource::ExactLookup,
            )
            .await;
        }
        Ok(Json(ToolOutcome::success(GetMessageResult { message })))
    }

