    /// Read bounded channel/supergroup moderation history with source filters and a stable cursor.
    #[tool(annotations(
        title = "Get Telegram admin log",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn get_admin_log(
        &self,
        Parameters(args): Parameters<GetAdminLogArgs>,
    ) -> Result<Json<ToolOutcome<AdminLogPage>>, Json<ToolOutcome<AdminLogPage>>> {
        validate_chat_id(&args.chat_id, "get_admin_log")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let query = args.query.trim().to_string();
        if query.encode_utf16().count() > MAX_ADMIN_LOG_QUERY_UTF16 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "get_admin_log.query must be <= {MAX_ADMIN_LOG_QUERY_UTF16} UTF-16 code units"
            )))));
        }
        if args.max_id < 0 || args.min_id < 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_admin_log.max_id and min_id must be non-negative",
            ))));
        }
        if args.max_id > 0 && args.min_id > 0 && args.min_id >= args.max_id {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_admin_log.min_id must be lower than max_id when both are provided",
            ))));
        }
        let limit = args.limit.unwrap_or(DEFAULT_ADMIN_LOG_LIMIT);
        if !(1..=MAX_ADMIN_LOG_LIMIT).contains(&limit) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "get_admin_log.limit must be between 1 and {MAX_ADMIN_LOG_LIMIT}"
            )))));
        }
        if args.admins.len() > MAX_ADMIN_LOG_ADMINS {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "get_admin_log.admins must contain <= {MAX_ADMIN_LOG_ADMINS} users"
            )))));
        }
        let mut seen_admins = HashSet::with_capacity(args.admins.len());
        let mut admins = Vec::with_capacity(args.admins.len());
        for admin in args.admins {
            let value = admin.0.trim();
            if value.is_empty() {
                return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                    "get_admin_log.admins must not contain empty user references",
                ))));
            }
            let normalized = value.trim_start_matches('@').to_lowercase();
            if !seen_admins.insert(normalized) {
                return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                    "get_admin_log.admins must not contain duplicates",
                ))));
            }
            admins.push(value.to_string());
        }
        let events = args.events.filter(|filter| !filter.is_empty());
        let page = self
            .backend
            .get_admin_log(
                None,
                &args.chat_id.0,
                &query,
                events,
                &admins,
                args.max_id,
                args.min_id,
                limit,
            )
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        Ok(Json(ToolOutcome::success(page)))
    }

