    /// Prepare one exact Telegram text message for future or online-triggered delivery.
    ///
    /// `source` is mandatory. Telegram sources are resolved and snapshotted by the server;
    /// public-web sources are validated as inert provenance metadata and hash-bound to the action.
    #[tool(annotations(
        title = "Prepare scheduled Telegram message",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_schedule_message(
        &self,
        Parameters(args): Parameters<PrepareScheduleMessageArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_schedule_message")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        match args.parse_mode {
            CaptionParseMode::RichMarkdown => {
                validate_rich_markdown(&args.text, "prepare_schedule_message.text")
            },
            _ => validate_mutation_text(&args.text, "prepare_schedule_message.text"),
        }
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.reply_to_message_id.is_some_and(|message_id| message_id <= 0) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_schedule_message.reply_to_message_id must be positive",
            ))));
        }
        let schedule_date_unix = resolve_schedule_date(
            args.schedule_at_unix,
            args.send_when_online,
            None,
            "prepare_schedule_message",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let target = self
            .resolve_prepared_send_target(&selected_session, &account, &canonical_chat_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let source = Some(
            self.resolve_prepared_outbound_source(&selected_session, &account, args.source)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error)))?,
        );
        let reply_to = if let Some(reply_to_message_id) = args.reply_to_message_id {
            let message = self
                .backend
                .get_message(
                    Some(selected_session),
                    &canonical_chat_id,
                    reply_to_message_id,
                )
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .ok_or_else(|| {
                    Json(ToolOutcome::failure(ToolFailure::new(
                        "MESSAGE_NOT_FOUND",
                        format!(
                            "reply target {reply_to_message_id} was not found in {canonical_chat_id}"
                        ),
                        false,
                    )))
                })?;
            Some(mutation_snapshot(&message))
        } else {
            None
        };
        let action = MutationAction::ScheduleMessage {
            chat_id: canonical_chat_id,
            target: Some(target),
            source,
            text: args.text,
            parse_mode: args.parse_mode,
            reply_to,
            schedule_date_unix,
            silent: args.silent,
            noforwards: args.noforwards,
            random_id: new_random_id(),
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

