    /// Prepare editing the text and/or delivery time of one scheduled message.
    #[tool(annotations(
        title = "Prepare scheduled Telegram message edit",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_edit_scheduled_message(
        &self,
        Parameters(args): Parameters<PrepareEditScheduledMessageArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_edit_scheduled_message")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_id <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_edit_scheduled_message.message_id must be positive",
            ))));
        }
        if let Some(text) = &args.text {
            match args.parse_mode {
                CaptionParseMode::RichMarkdown => {
                    validate_rich_markdown(text, "prepare_edit_scheduled_message.text")
                },
                _ => validate_mutation_text(text, "prepare_edit_scheduled_message.text"),
            }
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        }
        if args.text.is_none() && args.schedule_at_unix.is_none() && !args.send_when_online {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_edit_scheduled_message requires text or a new schedule",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let scheduled = self
            .backend
            .get_scheduled_messages(Some(selected_session), &canonical_chat_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let current = scheduled
            .iter()
            .find(|message| message.message_id == args.message_id)
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "SCHEDULED_MESSAGE_NOT_FOUND",
                    format!(
                        "scheduled message {} was not found in {canonical_chat_id}",
                        args.message_id
                    ),
                    false,
                )))
            })?;
        let schedule_date_unix = resolve_schedule_date(
            args.schedule_at_unix,
            args.send_when_online,
            Some(current.date),
            "prepare_edit_scheduled_message",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let text = args.text.unwrap_or_else(|| current.text.clone().unwrap_or_default());
        if current.text.as_deref().unwrap_or_default() == text && current.date == schedule_date_unix
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!(
                    "scheduled message {} already matches the requested state",
                    args.message_id
                ),
                false,
            ))));
        }
        let action = MutationAction::EditScheduledMessage {
            chat_id: canonical_chat_id,
            before: mutation_snapshot(current),
            text,
            parse_mode: args.parse_mode,
            schedule_date_unix,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

