    /// Prepare creating a Telegram poll or quiz with an exact immutable definition.
    #[tool(annotations(
        title = "Prepare Telegram poll",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_create_poll(
        &self,
        Parameters(args): Parameters<PrepareCreatePollArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_create_poll")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.reply_to_message_id.is_some_and(|message_id| message_id <= 0) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_create_poll.reply_to_message_id must be positive",
            ))));
        }
        let poll =
            validate_poll_create_args(&args).map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let reply_to = if let Some(message_id) = args.reply_to_message_id {
            let message = self
                .backend
                .get_message(Some(selected_session), &canonical_chat_id, message_id)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .ok_or_else(|| {
                    Json(ToolOutcome::failure(ToolFailure::new(
                        "MESSAGE_NOT_FOUND",
                        format!("reply target {message_id} was not found in {canonical_chat_id}"),
                        false,
                    )))
                })?;
            Some(mutation_snapshot(&message))
        } else {
            None
        };
        let action = MutationAction::CreatePoll {
            chat_id: canonical_chat_id,
            poll,
            reply_to,
            silent: args.silent,
            noforwards: args.noforwards,
            random_id: new_random_id(),
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare casting, changing, or retracting the authenticated account's exact poll vote.
    #[tool(annotations(
        title = "Prepare Telegram poll vote",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_set_poll_vote(
        &self,
        Parameters(args): Parameters<PrepareSetPollVoteArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_set_poll_vote")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_id <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_set_poll_vote.message_id must be positive",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let poll = self
            .backend
            .get_poll(Some(selected_session), &canonical_chat_id, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "POLL_NOT_FOUND",
                    format!(
                        "poll message {} was not found in {canonical_chat_id}",
                        args.message_id
                    ),
                    false,
                )))
            })?;
        if poll.closed {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "POLL_CLOSED",
                format!("poll message {} is already closed", args.message_id),
                false,
            ))));
        }
        let mut requested = args.option_indices;
        requested.sort_unstable();
        if requested.windows(2).any(|pair| matches!(pair, [left, right] if left == right)) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_set_poll_vote.option_indices must not contain duplicates",
            ))));
        }
        if !poll.multiple_choice && requested.len() > 1 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "this poll accepts at most one answer",
            ))));
        }
        let options = requested
            .iter()
            .map(|index| {
                poll.answers
                    .iter()
                    .find(|answer| answer.option.index == *index)
                    .map(|answer| answer.option.clone())
                    .ok_or_else(|| {
                        ToolFailure::invalid_argument(format!(
                            "poll option index {index} was not found"
                        ))
                    })
            })
            .collect::<Result<Vec<PollOptionBinding>, ToolFailure>>()
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let before = poll.mutation_snapshot();
        if before.selected_option_indices == requested {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                "the authenticated account already has the requested poll vote",
                false,
            ))));
        }
        if poll.revoting_disabled && !before.selected_option_indices.is_empty() {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "POLL_REVOTING_DISABLED",
                "this poll does not allow changing or retracting an existing vote",
                false,
            ))));
        }
        let action = MutationAction::SetPollVote { chat_id: canonical_chat_id, before, options };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare closing one exact Telegram poll so it accepts no further votes.
    #[tool(annotations(
        title = "Prepare stop Telegram poll",
        read_only_hint = false,
        destructive_hint = true,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_stop_poll(
        &self,
        Parameters(args): Parameters<PrepareStopPollArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_stop_poll")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_id <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_stop_poll.message_id must be positive",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let poll = self
            .backend
            .get_poll(Some(selected_session), &canonical_chat_id, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "POLL_NOT_FOUND",
                    format!(
                        "poll message {} was not found in {canonical_chat_id}",
                        args.message_id
                    ),
                    false,
                )))
            })?;
        if poll.closed {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!("poll message {} is already closed", args.message_id),
                false,
            ))));
        }
        if poll.attached_media_type.is_some() || poll.solution_has_media {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "POLL_MEDIA_PRESERVATION_UNAVAILABLE",
                "stopping this poll would require exact attached-media preservation that is not yet supported",
                false,
            ))));
        }
        let action = MutationAction::StopPoll {
            chat_id: canonical_chat_id,
            before: poll.mutation_snapshot(),
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

