    /// List Telegram's default, recent, channel-default, or collectible emoji statuses.
    #[tool(annotations(
        title = "List Telegram emoji statuses",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn list_emoji_statuses(
        &self,
        Parameters(args): Parameters<ListEmojiStatusesArgs>,
    ) -> Result<Json<ToolOutcome<EmojiStatusCatalogPage>>, Json<ToolOutcome<EmojiStatusCatalogPage>>>
    {
        let kind = args.kind.unwrap_or(EmojiStatusCatalogKind::Default);
        let limit = validate_limit(
            args.limit.unwrap_or(DEFAULT_EMOJI_STATUS_LIMIT),
            MAX_EMOJI_STATUS_LIMIT,
            "list_emoji_statuses.limit",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let hash = parse_optional_i64_decimal(args.hash.as_deref(), "list_emoji_statuses.hash")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let page = self
            .backend
            .list_emoji_statuses(None, kind, hash)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let page = limit_emoji_status_page(page, kind, hash, limit)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        Ok(Json(ToolOutcome::success(page)))
    }

