    /// List or search topics in one Telegram forum supergroup.
    #[tool(annotations(
        title = "List Telegram forum topics",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn list_forum_topics(
        &self,
        Parameters(args): Parameters<ListForumTopicsArgs>,
    ) -> Result<Json<ToolOutcome<ListForumTopicsResult>>, Json<ToolOutcome<ListForumTopicsResult>>>
    {
        validate_chat_id(&args.chat_id, "list_forum_topics")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let query = args.query.as_deref().map(str::trim).filter(|query| !query.is_empty());
        if query.is_some_and(|query| query.chars().count() > 128) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "list_forum_topics.query must be <= 128 characters",
            ))));
        }
        for (name, value) in [
            ("offset_date", args.offset_date.unwrap_or_default()),
            ("offset_id", args.offset_id.unwrap_or_default()),
            ("offset_topic", args.offset_topic.unwrap_or_default()),
        ] {
            if value < 0 {
                return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                    "list_forum_topics.{name} must be zero or positive"
                )))));
            }
        }
        let limit = validate_limit(
            args.limit.unwrap_or(DEFAULT_REPLIES_LIMIT),
            MAX_REPLIES_LIMIT,
            "list_forum_topics.limit",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let chat_id = args.chat_id.0;
        let topics = self
            .backend
            .list_forum_topics(
                None,
                &chat_id,
                query,
                limit,
                args.offset_date.unwrap_or_default(),
                args.offset_id.unwrap_or_default(),
                args.offset_topic.unwrap_or_default(),
            )
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        Ok(Json(ToolOutcome::success(ListForumTopicsResult {
            chat_id,
            returned_count: topics.len(),
            topics,
        })))
    }

