    /// Read a bounded page of messages inside one exact forum topic.
    #[tool(annotations(
        title = "Read Telegram forum topic messages",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn read_topic_messages(
        &self,
        Parameters(args): Parameters<ReadTopicMessagesArgs>,
    ) -> Result<Json<ToolOutcome<MessagePage>>, Json<ToolOutcome<MessagePage>>> {
        validate_forum_topic_target(&args.chat_id, args.topic_id, "read_topic_messages")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.offset_id.is_some_and(|offset| offset <= 0) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "read_topic_messages.offset_id must be positive when provided",
            ))));
        }
        let limit = validate_limit(
            args.limit.unwrap_or(DEFAULT_REPLIES_LIMIT),
            MAX_REPLIES_LIMIT,
            "read_topic_messages.limit",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let topic = self
            .backend
            .get_forum_topic(None, &args.chat_id.0, args.topic_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .filter(|topic| !topic.deleted)
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "FORUM_TOPIC_NOT_FOUND",
                    format!("forum topic {} was not found in {}", args.topic_id, args.chat_id.0),
                    false,
                )))
            })?;
        let top_message_id = topic.top_message_id.ok_or_else(|| {
            Json(ToolOutcome::failure(ToolFailure::new(
                "FORUM_TOPIC_HISTORY_UNAVAILABLE",
                format!("forum topic {} has no top message binding", args.topic_id),
                false,
            )))
        })?;
        let page = self
            .backend
            .get_replies(None, &args.chat_id.0, top_message_id, limit, args.offset_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        Ok(Json(ToolOutcome::success(page)))
    }

    /// Prepare creating one forum topic with a stable idempotency key.
    #[tool(annotations(
        title = "Prepare Telegram forum topic creation",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_create_forum_topic(
        &self,
        Parameters(args): Parameters<PrepareCreateForumTopicArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_create_forum_topic")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        validate_forum_topic_title(&args.title, "prepare_create_forum_topic.title")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        validate_forum_topic_icon(args.icon_color, args.icon_emoji_id, true)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        self.backend
            .list_forum_topics(Some(selected_session), &canonical_chat_id, None, 1, 0, 0, 0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let action = MutationAction::CreateForumTopic {
            chat_id: canonical_chat_id,
            title: args.title,
            icon_color: args.icon_color,
            icon_emoji_id: args.icon_emoji_id,
            random_id: new_random_id(),
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare editing the title, custom icon, closed state, or hidden state of one topic.
    #[tool(annotations(
        title = "Prepare Telegram forum topic edit",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_edit_forum_topic(
        &self,
        Parameters(args): Parameters<PrepareEditForumTopicArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_forum_topic_target(&args.chat_id, args.topic_id, "prepare_edit_forum_topic")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if let Some(title) = &args.title {
            validate_forum_topic_title(title, "prepare_edit_forum_topic.title")
                .map_err(|error| Json(ToolOutcome::failure(error)))?;
        }
        validate_forum_topic_icon(None, args.icon_emoji_id, false)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.title.is_none()
            && args.icon_emoji_id.is_none()
            && args.closed.is_none()
            && args.hidden.is_none()
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_edit_forum_topic requires at least one changed field",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let topic = require_forum_topic(
            self.backend.as_ref(),
            Some(selected_session),
            &canonical_chat_id,
            args.topic_id,
        )
        .await
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let before = topic.mutation_snapshot();
        if forum_topic_matches_edit(
            &topic,
            &before,
            args.title.as_deref(),
            args.icon_emoji_id,
            args.closed,
            args.hidden,
        ) {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!("forum topic {} already matches the requested state", args.topic_id),
                false,
            ))));
        }
        let action = MutationAction::EditForumTopic {
            chat_id: canonical_chat_id,
            before,
            title: args.title,
            icon_emoji_id: args.icon_emoji_id,
            closed: args.closed,
            hidden: args.hidden,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

