    /// Prepare an exact full replacement of one Telegram account privacy rule set.
    #[tool(annotations(
        title = "Prepare Telegram privacy rules",
        read_only_hint = false,
        destructive_hint = true,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_set_privacy_rules(
        &self,
        Parameters(args): Parameters<PrepareSetPrivacyRulesArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        if args.rules.is_empty() {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_set_privacy_rules.rules must not be empty",
            ))));
        }
        if args.rules.len() > MAX_PRIVACY_RULES {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "prepare_set_privacy_rules.rules must contain at most {MAX_PRIVACY_RULES} rules"
            )))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let before = self
            .backend
            .get_privacy_rules(Some(selected_session.clone()), args.key.clone())
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let (rules, user_bindings) = self
            .resolve_privacy_rules(&selected_session, account.user_id, args.rules)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if before == rules {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                "the selected Telegram privacy rule set already matches the requested replacement",
                false,
            ))));
        }
        let action =
            MutationAction::SetPrivacyRules { key: args.key, before, rules, user_bindings };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

