    /// Prepare sending one exact opaque sticker through the shared private approval ledger.
    #[tool(annotations(
        title = "Send Telegram sticker",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn send_sticker(
        &self,
        Parameters(args): Parameters<SendStickerArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "send_sticker")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        validate_sticker_set_short_name(&args.set_short_name, "send_sticker")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        validate_sticker_handle(&args.sticker_handle, "send_sticker")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.reply_to_message_id.is_some_and(|message_id| message_id <= 0) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "send_sticker.reply_to_message_id must be positive",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        if let Some(reply_to_message_id) = args.reply_to_message_id
            && self
                .backend
                .get_message(
                    Some(selected_session.clone()),
                    &canonical_chat_id,
                    reply_to_message_id,
                )
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .is_none()
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "MESSAGE_NOT_FOUND",
                format!("reply target {reply_to_message_id} was not found in {canonical_chat_id}"),
                false,
            ))));
        }
        let set = self
            .backend
            .get_sticker_set(Some(selected_session), &args.set_short_name, 0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let sticker = set
            .stickers
            .into_iter()
            .find(|sticker| sticker.sticker_handle == args.sticker_handle)
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "STICKER_NOT_FOUND",
                    "the opaque sticker handle was not found in the selected sticker set",
                    false,
                )))
            })?;
        if sticker.custom_emoji {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "UNSUPPORTED_STICKER_KIND",
                "custom emoji documents are not ordinary sendable stickers",
                false,
            ))));
        }
        let action = MutationAction::SendSticker {
            chat_id: canonical_chat_id,
            sticker,
            reply_to_message_id: args.reply_to_message_id,
            silent: args.silent,
            noforwards: args.noforwards,
            random_id: new_random_id(),
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

