    /// Prepare adding or removing one exact opaque sticker from account favourites.
    #[tool(annotations(
        title = "Set Telegram sticker favourite",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn set_sticker_favorite(
        &self,
        Parameters(args): Parameters<SetStickerFavoriteArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_sticker_set_short_name(&args.set_short_name, "set_sticker_favorite")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        validate_sticker_handle(&args.sticker_handle, "set_sticker_favorite")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let sticker = self
            .backend
            .get_sticker_set(Some(selected_session.clone()), &args.set_short_name, 0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .stickers
            .into_iter()
            .find(|sticker| sticker.sticker_handle == args.sticker_handle)
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "STICKER_NOT_FOUND",
                    "the opaque sticker handle was not found in the selected sticker set",
                    false,
                )))
            })?;
        if sticker.custom_emoji {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "UNSUPPORTED_STICKER_KIND",
                "custom emoji documents cannot be added to sticker favourites",
                false,
            ))));
        }
        let before_favorite = self
            .backend
            .get_favorite_stickers(Some(selected_session), MAX_STICKER_CATALOG_LIMIT, 0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .stickers
            .iter()
            .any(|favorite| favorite.sticker_handle == sticker.sticker_handle);
        if before_favorite == args.favorite {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!(
                    "sticker {} favourite state is already {}",
                    sticker.sticker_handle, args.favorite
                ),
                false,
            ))));
        }
        let action = MutationAction::SetStickerFavorite {
            sticker,
            before_favorite,
            favorite: args.favorite,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare adding or removing one exact opaque sticker from a Telegram recent list.
