    /// Resolve custom-emoji document ids into safe metadata and opaque document handles.
    #[tool(annotations(
        title = "Get Telegram custom emoji documents",
        read_only_hint = true,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn get_custom_emoji_documents(
        &self,
        Parameters(args): Parameters<GetCustomEmojiDocumentsArgs>,
    ) -> Result<
        Json<ToolOutcome<CustomEmojiDocumentsPage>>,
        Json<ToolOutcome<CustomEmojiDocumentsPage>>,
    > {
        validate_custom_emoji_document_ids(&args.document_ids, "get_custom_emoji_documents")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let documents = self
            .backend
            .get_custom_emoji_documents(None, &args.document_ids)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let returned_ids =
            documents.iter().map(|document| document.document_id).collect::<HashSet<_>>();
        let missing_document_ids = args
            .document_ids
            .iter()
            .copied()
            .filter(|document_id| !returned_ids.contains(document_id))
            .collect::<Vec<_>>();
        Ok(Json(ToolOutcome::success(CustomEmojiDocumentsPage {
            requested_count: args.document_ids.len(),
            returned_count: documents.len(),
            missing_document_ids,
            documents,
        })))
    }

    /// Download one provider-resolved custom emoji into the managed immutable local cache.
    #[tool(annotations(
        title = "Download Telegram custom emoji",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn download_custom_emoji(
        &self,
        Parameters(args): Parameters<DownloadCustomEmojiArgs>,
    ) -> Result<Json<ToolOutcome<DownloadedCustomEmoji>>, Json<ToolOutcome<DownloadedCustomEmoji>>>
    {
        validate_custom_emoji_document_id(args.document_id, "download_custom_emoji")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let custom_emoji = self
            .backend
            .get_custom_emoji_documents(Some(selected_session.clone()), &[args.document_id])
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .into_iter()
            .find(|document| document.document_id == args.document_id)
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "CUSTOM_EMOJI_NOT_FOUND",
                    format!("custom emoji document {} was not found", args.document_id),
                    false,
                )))
            })?;
        if custom_emoji.sticker.size_bytes > self.settings.max_download_bytes {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "ATTACHMENT_TOO_LARGE",
                format!(
                    "custom emoji is {} bytes; configured maximum is {} bytes",
                    custom_emoji.sticker.size_bytes, self.settings.max_download_bytes
                ),
                false,
            ))));
        }

        let account_cache_dir =
            self.settings.attachment_cache_dir.join(account_cache_key(account.user_id));
        let custom_emoji_cache_dir =
            account_cache_dir.join(custom_emoji_cache_key(args.document_id));
        tokio::fs::create_dir_all(&custom_emoji_cache_dir)
            .await
            .map_err(|error| Json(ToolOutcome::failure(io_failure(error))))?;
        restrict_private_directory(&account_cache_dir)
            .and_then(|()| restrict_private_directory(&custom_emoji_cache_dir))
            .map_err(|error| Json(ToolOutcome::failure(io_failure(error))))?;
        let file_name = custom_emoji_file_name(&custom_emoji.sticker);
        let temporary = custom_emoji_cache_dir.join(format!(".{}.part", Uuid::new_v4()));
        let bytes_written = match self
            .backend
            .download_custom_emoji_to(
                Some(selected_session),
                args.document_id,
                &temporary,
                self.settings.max_download_bytes,
            )
            .await
        {
            Ok(bytes_written) => bytes_written,
            Err(error) => {
                let _ = tokio::fs::remove_file(&temporary).await;
                return Err(Json(ToolOutcome::failure(error.into())));
            },
        };
        restrict_private_file(&temporary)
            .map_err(|error| Json(ToolOutcome::failure(io_failure(error))))?;
        if bytes_written > self.settings.max_download_bytes {
            let _ = tokio::fs::remove_file(&temporary).await;
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "ATTACHMENT_TOO_LARGE",
                format!(
                    "download produced {bytes_written} bytes; configured maximum is {} bytes",
                    self.settings.max_download_bytes
                ),
                false,
            ))));
        }
        let sha256 = match sha256_file(&temporary).await {
            Ok(sha256) => sha256,
            Err(error) => {
                let _ = tokio::fs::remove_file(&temporary).await;
                return Err(Json(ToolOutcome::failure(io_failure(error))));
            },
        };
        let destination =
            publish_download(&temporary, &custom_emoji_cache_dir, &file_name, &sha256)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error)))?;
        Ok(Json(ToolOutcome::success(DownloadedCustomEmoji {
            custom_emoji,
            local_path: destination.display().to_string(),
            bytes_written,
            sha256,
        })))
    }

