    /// Prepare one exact static location for approval-backed Telegram delivery.
    #[tool(annotations(
        title = "Send Telegram location",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn send_location(
        &self,
        Parameters(args): Parameters<SendLocationArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        let point = validate_geo_point(
            args.latitude,
            args.longitude,
            args.accuracy_radius_m,
            "send_location",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.live_period_seconds.is_some_and(|period| {
            !(MIN_LIVE_LOCATION_PERIOD_SECONDS..=MAX_LIVE_LOCATION_PERIOD_SECONDS).contains(&period)
        }) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "send_location.live_period_seconds must be between {MIN_LIVE_LOCATION_PERIOD_SECONDS} and {MAX_LIVE_LOCATION_PERIOD_SECONDS}"
            )))));
        }
        if args.heading_degrees.is_some_and(|heading| !(1..=360).contains(&heading)) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "send_location.heading_degrees must be between 1 and 360",
            ))));
        }
        if args.proximity_notification_radius_m.is_some_and(|radius| radius <= 0) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "send_location.proximity_notification_radius_m must be positive",
            ))));
        }
        if args.live_period_seconds.is_none()
            && (args.heading_degrees.is_some() || args.proximity_notification_radius_m.is_some())
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "send_location heading/proximity fields require live_period_seconds",
            ))));
        }
        let prepared = self
            .prepare_rich_media_action(
                &args.chat_id,
                RichMediaSpec::Location {
                    point,
                    live_period_seconds: args.live_period_seconds,
                    heading_degrees: args.heading_degrees,
                    proximity_notification_radius_m: args.proximity_notification_radius_m,
                },
                args.caption,
                args.reply_to_message_id,
                args.topic_id,
                args.silent,
                args.noforwards,
                "send_location",
            )
            .await
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        Ok(Json(ToolOutcome::success(prepared)))
    }

