    /// Download one exact Telegram media, photo, file, or other attachment into the managed local cache.
    #[tool(annotations(
        title = "Download Telegram attachment",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn download_attachment(
        &self,
        Parameters(args): Parameters<AttachmentArgs>,
    ) -> Result<Json<ToolOutcome<DownloadedAttachment>>, Json<ToolOutcome<DownloadedAttachment>>>
    {
        validate_attachment_args(&args, "download_attachment")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let attachments = self
            .backend
            .list_attachments(Some(selected_session.clone()), &args.chat_id.0, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let attachment = attachments.into_iter().next().ok_or_else(|| {
            Json(ToolOutcome::failure(ToolFailure::new(
                "ATTACHMENT_NOT_FOUND",
                format!("{}:{} has no downloadable attachment", args.chat_id.0, args.message_id),
                false,
            )))
        })?;
        if let Some(size) = attachment.size_bytes
            && size > self.settings.max_download_bytes
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "ATTACHMENT_TOO_LARGE",
                format!(
                    "attachment is {size} bytes; configured maximum is {} bytes",
                    self.settings.max_download_bytes
                ),
                false,
            ))));
        }

        let account_cache_dir =
            self.settings.attachment_cache_dir.join(account_cache_key(account.user_id));
        let attachment_cache_dir =
            account_cache_dir.join(attachment_cache_key(&attachment.attachment_id));
        tokio::fs::create_dir_all(&attachment_cache_dir)
            .await
            .map_err(|error| Json(ToolOutcome::failure(io_failure(error))))?;
        restrict_private_directory(&account_cache_dir)
            .and_then(|()| restrict_private_directory(&attachment_cache_dir))
            .map_err(|error| Json(ToolOutcome::failure(io_failure(error))))?;
        let file_name = sanitize_file_name(
            attachment.file_name.as_deref().unwrap_or("telegram-attachment.bin"),
        );
        let temporary = attachment_cache_dir.join(format!(".{}.part", Uuid::new_v4()));
        let bytes_written = match self
            .backend
            .download_attachment_to(
                Some(selected_session),
                &args.chat_id.0,
                args.message_id,
                &temporary,
                self.settings.max_download_bytes,
            )
            .await
        {
            Ok(bytes_written) => bytes_written,
            Err(error) => {
                let _ = tokio::fs::remove_file(&temporary).await;
                return Err(Json(ToolOutcome::failure(error.into())));
            },
        };
        restrict_private_file(&temporary)
            .map_err(|error| Json(ToolOutcome::failure(io_failure(error))))?;
        if bytes_written > self.settings.max_download_bytes {
            let _ = tokio::fs::remove_file(&temporary).await;
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "ATTACHMENT_TOO_LARGE",
                format!(
                    "download produced {bytes_written} bytes; configured maximum is {} bytes",
                    self.settings.max_download_bytes
                ),
                false,
            ))));
        }
        let sha256 = match sha256_file(&temporary).await {
            Ok(sha256) => sha256,
            Err(error) => {
                let _ = tokio::fs::remove_file(&temporary).await;
                return Err(Json(ToolOutcome::failure(io_failure(error))));
            },
        };
        let destination = publish_download(&temporary, &attachment_cache_dir, &file_name, &sha256)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        Ok(Json(ToolOutcome::success(DownloadedAttachment {
            attachment,
            local_path: destination.display().to_string(),
            bytes_written,
            sha256,
        })))
    }

    async fn resolve_prepared_send_target(
        &self,
        selected_session: &std::path::Path,
        account: &crate::telegram::UserInfo,
        canonical_chat_id: &str,
    ) -> Result<PreparedSendTarget, ToolFailure> {
        if canonical_chat_id == account.user_id.to_string() {
            return Ok(PreparedSendTarget {
                display_name: "Избранное".to_string(),
                username: account.username.clone(),
                kind: "saved_messages".to_string(),
            });
        }
        let peer_id = canonical_chat_id.parse::<i64>().map_err(|_| {
            ToolFailure::new(
                "STATE_INTEGRITY_ERROR",
                "Telegram returned a non-numeric canonical destination",
                false,
            )
        })?;
        if peer_id > 0 {
            let details = self
                .backend
                .get_user_info(Some(selected_session.to_path_buf()), canonical_chat_id)
                .await
                .map_err(ToolFailure::from)?;
            if details.user.user_id != peer_id {
                return Err(ToolFailure::new(
                    "STATE_INTEGRITY_ERROR",
                    "Telegram returned an identity that does not match the resolved destination",
                    false,
                ));
            }
            return Ok(PreparedSendTarget {
                display_name: details.user.display_name,
                username: details.user.username,
                kind: if details.user.bot { "bot" } else { "user" }.to_string(),
            });
        }
        let lifecycle = self
            .backend
            .get_chat_lifecycle_state(Some(selected_session.to_path_buf()), canonical_chat_id)
            .await
            .map_err(ToolFailure::from)?;
        if lifecycle.details.chat.chat_id != canonical_chat_id {
            return Err(ToolFailure::new(
                "STATE_INTEGRITY_ERROR",
                "Telegram returned a chat identity that does not match the resolved destination",
                false,
            ));
        }
        Ok(PreparedSendTarget {
            display_name: lifecycle.details.chat.title,
            username: lifecycle.details.chat.username,
            kind: lifecycle.details.chat.kind,
        })
    }

    async fn resolve_prepared_message_source(
        &self,
        selected_session: &std::path::Path,
        account: &crate::telegram::UserInfo,
        source: PrepareMessageSourceArgs,
        relation: OutboundSourceRelation,
    ) -> Result<PreparedMessageSource, ToolFailure> {
        validate_chat_id(&source.chat_id, "prepare_schedule_message.source.chat_id")?;
        if source.message_id <= 0 {
            return Err(ToolFailure::invalid_argument(
                "prepare_schedule_message.source.message_id must be positive",
            ));
        }
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.to_path_buf()), &source.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let message = self
            .backend
            .get_message(
                Some(selected_session.to_path_buf()),
                &canonical_chat_id,
                source.message_id,
            )
            .await
            .map_err(ToolFailure::from)?
            .ok_or_else(|| {
                ToolFailure::new(
                    "SOURCE_MESSAGE_NOT_FOUND",
                    format!(
                        "source message {} was not found in {}",
                        source.message_id, canonical_chat_id
                    ),
                    false,
                )
            })?;
        if message.message_id != source.message_id {
            return Err(ToolFailure::new(
                "STATE_INTEGRITY_ERROR",
                "Telegram returned a source message with a different identity",
                false,
            ));
        }
        let target = self
            .resolve_prepared_send_target(selected_session, account, &canonical_chat_id)
            .await?;
        Ok(PreparedMessageSource {
            chat_id: canonical_chat_id,
            target,
            message_id: message.message_id,
            message_date_unix: message.date,
            text: message.text,
            relation: Some(relation),
        })
    }

    async fn resolve_prepared_outbound_source(
        &self,
        selected_session: &std::path::Path,
        account: &crate::telegram::UserInfo,
        source: PrepareOutboundSourceArgs,
    ) -> Result<PreparedOutboundSource, ToolFailure> {
        match source {
            PrepareOutboundSourceArgs::TelegramMessage { relation, chat_id, message_id } => self
                .resolve_prepared_message_source(
                    selected_session,
                    account,
                    PrepareMessageSourceArgs { chat_id, message_id },
                    relation,
                )
                .await
                .map(PreparedOutboundSource::TelegramMessage),
            PrepareOutboundSourceArgs::PublicWeb {
                relation,
                publisher,
                title,
                url,
                published_at_unix,
                observed_at_unix,
            } => {
                let publisher = validate_source_label(publisher, "prepare source.publisher", 160)?;
                let title = validate_source_label(title, "prepare source.title", 320)?;
                let url = validate_public_source_url(&url)?;
                validate_source_timestamps(published_at_unix, observed_at_unix)?;
                Ok(PreparedOutboundSource::NonTelegram(PreparedNonTelegramSource::PublicWeb {
                    relation,
                    publisher,
                    title,
                    url,
                    published_at_unix,
                    observed_at_unix,
                }))
            },
            PrepareOutboundSourceArgs::SelfOriginated => {
                Ok(PreparedOutboundSource::NonTelegram(PreparedNonTelegramSource::SelfOriginated))
            },
        }
    }

    /// Prepare an immutable plain-text Telegram message without sending it.
    #[tool(annotations(
        title = "Prepare Telegram message",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn prepare_message(
        &self,
        Parameters(args): Parameters<PrepareMessageArgs>,
    ) -> Result<Json<ToolOutcome<PreparedSend>>, Json<ToolOutcome<PreparedSend>>> {
        validate_chat_id(&args.chat_id, "prepare_message")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.text.trim().is_empty() {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_message.text must not be empty",
            ))));
        }
        if args.reply_to_message_id.is_some_and(|message_id| message_id <= 0) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_message.reply_to_message_id must be positive",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        if let Some(reply_to_message_id) = args.reply_to_message_id
            && self
                .backend
                .get_message(
                    Some(selected_session.clone()),
                    &canonical_chat_id,
                    reply_to_message_id,
                )
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .is_none()
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "MESSAGE_NOT_FOUND",
                format!("reply target {reply_to_message_id} was not found in {canonical_chat_id}"),
                false,
            ))));
        }
        let target = self
            .resolve_prepared_send_target(&selected_session, &account, &canonical_chat_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let source = self
            .resolve_prepared_outbound_source(&selected_session, &account, args.source)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let payload_sha256 = prepared_payload_hash(
            account.user_id,
            &canonical_chat_id,
            &target,
            &source,
            PreparedSendKind::PlainText,
            &args.text,
            args.reply_to_message_id,
        );
        let record = self
            .send_ledger
            .prepare(
                account.user_id,
                canonical_chat_id,
                target,
                source,
                args.text,
                args.reply_to_message_id,
                payload_sha256,
            )
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(record.public)))
    }

