    /// Send structured Rich Text directly to the authenticated account's Saved Messages.
    ///
    /// The tool has no recipient parameter: a non-self destination cannot be constructed.
    #[tool(annotations(
        title = "Send Rich Text to Saved Messages",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn send_saved_rich_message(
        &self,
        Parameters(args): Parameters<SendSavedRichMessageArgs>,
    ) -> Result<Json<ToolOutcome<SendRichMessageResult>>, Json<ToolOutcome<SendRichMessageResult>>>
    {
        validate_rich_markdown(&args.markdown, "send_saved_rich_message.markdown")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        validate_optional_message_id(
            args.reply_to_message_id,
            "send_saved_rich_message.reply_to_message_id",
        )
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let self_chat_id = account.user_id.to_string();
        if let Some(reply_to_message_id) = args.reply_to_message_id
            && self
                .backend
                .get_message(Some(selected_session.clone()), &self_chat_id, reply_to_message_id)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .is_none()
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "MESSAGE_NOT_FOUND",
                format!(
                    "reply target {reply_to_message_id} was not found in Saved Messages for account {}",
                    account.user_id
                ),
                false,
            ))));
        }
        let message_id = self
            .backend
            .send_rich_markdown_with_random_id(
                Some(selected_session.clone()),
                &self_chat_id,
                &args.markdown,
                args.reply_to_message_id,
                new_random_id(),
            )
            .await
            .map_err(|error| Json(ToolOutcome::failure(direct_send_failure(error))))?;
        let readback = self
            .backend
            .get_rich_message_snapshot(Some(selected_session), &self_chat_id, message_id)
            .await
            .map_err(|error| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "RICH_MESSAGE_READBACK_UNCONFIRMED",
                    format!(
                        "Telegram returned message_id {message_id}, but structured readback failed; do not resend blindly: {error}"
                    ),
                    false,
                )))
            })?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "RICH_MESSAGE_READBACK_UNCONFIRMED",
                    format!(
                        "Telegram returned message_id {message_id}, but messages.getRichMessage returned no structured payload; do not resend blindly"
                    ),
                    false,
                )))
            })?;
        if readback.chat_id != self_chat_id || readback.message_id != message_id {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "RICH_MESSAGE_READBACK_MISMATCH",
                format!(
                    "Telegram returned message_id {message_id}, but rich-message readback was bound to {}:{}; do not resend blindly",
                    readback.chat_id, readback.message_id
                ),
                false,
            ))));
        }
        Ok(Json(ToolOutcome::success(SendRichMessageResult {
            status: "sent_and_verified".to_string(),
            message_id,
            chat_id: self_chat_id,
            readback,
        })))
    }

