    /// Send a hash-bound approval card to the configured private Telegram bot chat.
    #[tool(annotations(
        title = "Request Telegram send approval",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn request_send_approval(
        &self,
        Parameters(args): Parameters<RequestSendApprovalArgs>,
    ) -> Result<Json<ToolOutcome<SendApproval>>, Json<ToolOutcome<SendApproval>>> {
        if args.draft_id.trim().is_empty() {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "request_send_approval.draft_id must not be empty",
            ))));
        }
        let runtime = self.approval.as_ref().ok_or_else(|| {
            Json(ToolOutcome::failure(ToolFailure::new(
                "APPROVAL_NOT_CONFIGURED",
                "Telegram button approval is not configured for this MCP server",
                false,
            )))
        })?;
        let prepared = self
            .send_ledger
            .get(&args.draft_id)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "DRAFT_NOT_FOUND",
                    format!("prepared message {} was not found", args.draft_id),
                    false,
                )))
            })?;
        if args.approved_payload_sha256 != prepared.public.payload_sha256 {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "PAYLOAD_HASH_MISMATCH",
                "request_send_approval.approved_payload_sha256 does not match the immutable prepared payload",
                false,
            ))));
        }
        let request = self
            .send_ledger
            .create_or_get_approval(
                &args.draft_id,
                &args.approved_payload_sha256,
                runtime.policy.approval_chat_id,
                runtime.policy.approval_user_id,
                runtime.policy.ttl_seconds,
            )
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        // Idempotent repeat: a sent or in-flight approval never triggers a
        // second Telegram send. The same receipt is returned without consuming
        // another owner-grant message or dispatching another card.
        if matches!(
            request.public.state,
            SendApprovalState::Sent
                | SendApprovalState::Sending
                | SendApprovalState::DeliveryUncertain
        ) {
            return Ok(Json(ToolOutcome::success(request.public)));
        }
        // Owner grant + durable owner permissions (#1598): the owner authorized
        // this host or peer in words ("да, отправляй" / "мигрируем на
        // прежнего бота"). The card is skipped only for the exact peers a live
        // record names; the grant's budget/expiry and the permission's
        // evidence/expiry/use-limit are enforced inside the consumers, and
        // every use is journalled. With no matching record this path is
        // unchanged.
        let peers = [
            prepared.public.chat_id.as_str(),
            prepared.public.target.username.as_deref().unwrap_or(""),
            prepared.public.target.display_name.as_str(),
        ];
        let coverage = runtime
            .policy
            .owner_grant_file
            .as_deref()
            .and_then(|path| {
                crate::approval::consume_owner_grant(path, &peers, now_unix()).map(CoveredBy::Grant)
            })
            .or_else(|| {
                runtime.policy.owner_permission_file.as_deref().and_then(|path| {
                    crate::approval::consume_owner_permission(
                        path,
                        &peers,
                        "send_message",
                        now_unix(),
                    )
                    .map(CoveredBy::Permission)
                })
            });
        if let Some(coverage) = coverage {
            let permission_id = match &coverage {
                CoveredBy::Grant(_) => None,
                CoveredBy::Permission(lease) => Some(lease.use_record.id),
            };
            match &coverage {
                CoveredBy::Grant(grant_use) => tracing::info!(
                    target: "telegram_personal_mcp",
                    target = %grant_use.target,
                    remaining_messages = grant_use.remaining_messages,
                    granted_by = grant_use.granted_by,
                    "owner grant covered this send; approval card skipped"
                ),
                CoveredBy::Permission(lease) => tracing::info!(
                    target: "telegram_personal_mcp",
                    permission_id = lease.use_record.id,
                    subject = %lease.use_record.subject,
                    target = %lease.use_record.target,
                    used = lease.use_record.used,
                    max_uses = lease.use_record.max_uses,
                    "owner permission covered this send; approval card skipped"
                ),
            }
            self.send_ledger
                .mark_approval_card_skipped(&request.public.approval_id)
                .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
            let claimed = self
                .send_ledger
                .mark_approval_sending(&request.public.approval_id, now_unix())
                .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
            if !claimed {
                // Never silently drop a `false`: the approval left the
                // pending window (expired, cancelled, or already claimed).
                // A sent/in-flight receipt is returned without a second
                // send; anything else is an honest, non-retryable refusal.
                let current = self
                    .send_ledger
                    .get_approval(&request.public.approval_id)
                    .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
                    .ok_or_else(|| {
                        Json(ToolOutcome::failure(ToolFailure::new(
                            "APPROVAL_NOT_FOUND",
                            "approval disappeared after its card was skipped",
                            false,
                        )))
                    })?;
                if matches!(
                    current.state,
                    SendApprovalState::Sent
                        | SendApprovalState::Sending
                        | SendApprovalState::DeliveryUncertain
                ) {
                    return Ok(Json(ToolOutcome::success(current)));
                }
                return Err(Json(ToolOutcome::failure(ToolFailure::new(
                    "APPROVAL_NOT_SENDABLE",
                    format!(
                        "a cardless authorization cannot send approval {} from state {:?}: only a pending approval can enter sending",
                        current.approval_id, current.state
                    ),
                    false,
                ))));
            }
            // The entry lease covered the ledger transition; release it, then
            // re-read the mirror under the writer-shared lock immediately
            // before the provider action. A revoke or a stale export that
            // landed in between must deny the send instead of authorizing an
            // action the owner no longer approves.
            drop(coverage);
            let _permission_guard = match permission_id {
                Some(permission_id) => {
                    let path = runtime
                        .policy
                        .owner_permission_file
                        .as_deref()
                        .expect("a permission lease implies a configured owner permission file");
                    match crate::approval::revalidate_owner_permission(
                        path,
                        permission_id,
                        &peers,
                        "send_message",
                        now_unix(),
                    ) {
                        Ok(Some(lease)) => Some(lease),
                        Ok(None) | Err(_) => {
                            self.send_ledger
                                .mark_approval_known_send_failure(
                                    &request.public.approval_id,
                                    "OWNER_PERMISSION_REVALIDATION_FAILED",
                                    now_unix(),
                                )
                                .map_err(|error| {
                                    Json(ToolOutcome::failure(ledger_failure(error)))
                                })?;
                            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                                "OWNER_PERMISSION_REVALIDATION_FAILED",
                                "the owner permission no longer authorizes this send; the approval card is required again",
                                false,
                            ))));
                        },
                    }
                },
                None => None,
            };
            // The snapshot captured before the transition still says
            // dispatching_card; the send path requires the reloaded sending
            // state, the same way a granted mutation reloads applying.
            let sending = self
                .reload_approval(&request.public.approval_id)
                .map_err(|error| Json(ToolOutcome::failure(error)))?;
            self.complete_approval_send(runtime, sending)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error)))?;
            let final_state = self
                .reload_approval(&request.public.approval_id)
                .map_err(|error| Json(ToolOutcome::failure(error)))?;
            return Ok(Json(ToolOutcome::success(final_state)));
        }
        if !request.should_dispatch_card {
            return Ok(Json(ToolOutcome::success(request.public)));
        }

        match runtime.bot.send_card(&ApprovalCard { approval: request.public.clone() }).await {
            Ok(receipt) => {
                self.send_ledger
                    .mark_approval_card_delivered(&request.public.approval_id, receipt.message_id)
                    .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
                let delivered = self
                    .send_ledger
                    .get_approval(&request.public.approval_id)
                    .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
                    .ok_or_else(|| {
                        Json(ToolOutcome::failure(ToolFailure::new(
                            "APPROVAL_NOT_FOUND",
                            "approval disappeared after its Telegram card was delivered",
                            false,
                        )))
                    })?;
                Ok(Json(ToolOutcome::success(delivered)))
            },
            Err(error) if error.delivery_uncertain => {
                self.send_ledger
                    .mark_approval_card_uncertain(&request.public.approval_id, error.code)
                    .map_err(|ledger_error| {
                        Json(ToolOutcome::failure(ledger_failure(ledger_error)))
                    })?;
                let uncertain = self
                    .send_ledger
                    .get_approval(&request.public.approval_id)
                    .map_err(|ledger_error| {
                        Json(ToolOutcome::failure(ledger_failure(ledger_error)))
                    })?
                    .ok_or_else(|| {
                        Json(ToolOutcome::failure(ToolFailure::new(
                            "APPROVAL_NOT_FOUND",
                            "approval disappeared after an uncertain card delivery",
                            false,
                        )))
                    })?;
                Ok(Json(ToolOutcome::success(uncertain)))
            },
            Err(error) => {
                self.send_ledger
                    .mark_approval_failed(&request.public.approval_id, error.code)
                    .map_err(|ledger_error| {
                        Json(ToolOutcome::failure(ledger_failure(ledger_error)))
                    })?;
                Err(Json(ToolOutcome::failure(approval_bot_failure(error.code))))
            },
        }
    }

    /// Read the durable state and final receipt of one Telegram button approval.
    #[tool(annotations(
        title = "Get Telegram send approval",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = false
    ))]
    async fn get_send_approval(
        &self,
        Parameters(args): Parameters<GetSendApprovalArgs>,
    ) -> Result<Json<ToolOutcome<SendApproval>>, Json<ToolOutcome<SendApproval>>> {
        if args.approval_id.trim().is_empty() {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "get_send_approval.approval_id must not be empty",
            ))));
        }
        let approval = self
            .send_ledger
            .get_approval(&args.approval_id)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "APPROVAL_NOT_FOUND",
                    format!("send approval {} was not found", args.approval_id),
                    false,
                )))
            })?;
        Ok(Json(ToolOutcome::success(approval)))
    }

    /// Cancel one exact pending send approval and remove its live action buttons.
    #[tool(annotations(
        title = "Cancel Telegram send approval",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn cancel_send_approval(
        &self,
        Parameters(args): Parameters<CancelSendApprovalArgs>,
    ) -> Result<Json<ToolOutcome<SendApproval>>, Json<ToolOutcome<SendApproval>>> {
        if args.approval_id.trim().is_empty() {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "cancel_send_approval.approval_id must not be empty",
            ))));
        }
        let runtime = self.approval.as_ref().ok_or_else(|| {
            Json(ToolOutcome::failure(ToolFailure::new(
                "APPROVAL_NOT_CONFIGURED",
                "Telegram button approval is not configured for this MCP server",
                false,
            )))
        })?;
        let approval = self
            .send_ledger
            .get_approval(&args.approval_id)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "APPROVAL_NOT_FOUND",
                    format!("send approval {} was not found", args.approval_id),
                    false,
                )))
            })?;
        if approval.payload_sha256 != args.approved_payload_sha256 {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "PAYLOAD_HASH_MISMATCH",
                "cancel_send_approval.approved_payload_sha256 does not match the immutable prepared payload",
                false,
            ))));
        }
        if approval.state == SendApprovalState::Cancelled {
            return Ok(Json(ToolOutcome::success(approval)));
        }
        if !matches!(
            approval.state,
            SendApprovalState::DispatchingCard
                | SendApprovalState::Pending
                | SendApprovalState::CardDeliveryUncertain
        ) {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "APPROVAL_NOT_CANCELLABLE",
                format!(
                    "send approval is already in terminal or committed state {:?}",
                    approval.state
                ),
                false,
            ))));
        }
        if !self
            .send_ledger
            .cancel_approval(&approval.approval_id, now_unix())
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "APPROVAL_NOT_CANCELLABLE",
                "send approval changed state before cancellation could be committed",
                false,
            ))));
        }
        let cancelled = self
            .send_ledger
            .get_approval(&approval.approval_id)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "APPROVAL_NOT_FOUND",
                    "send approval disappeared after cancellation",
                    false,
                )))
            })?;
        self.edit_approval_card(runtime, &cancelled).await;
        Ok(Json(ToolOutcome::success(cancelled)))
    }

    /// Prepare an immutable edit bound to the exact current Telegram message state.
    #[tool(annotations(
        title = "Prepare Telegram message edit",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn prepare_edit_message(
        &self,
        Parameters(args): Parameters<PrepareEditMessageArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_edit_message")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_id <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_edit_message.message_id must be positive",
            ))));
        }
        let parse_mode = args.parse_mode;
        if matches!(parse_mode, CaptionParseMode::RichMarkdown) {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_edit_message.parse_mode rich_markdown is not supported for message edits",
            ))));
        }
        let requested = edit_input_message(&args.text, parse_mode)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        validate_mutation_text(&requested.text, "prepare_edit_message.text")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let message = self
            .backend
            .get_message(Some(selected_session.clone()), &canonical_chat_id, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "MESSAGE_NOT_FOUND",
                    format!("message {} was not found in {}", args.message_id, canonical_chat_id),
                    false,
                )))
            })?;
        if !message.outgoing {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "MESSAGE_NOT_EDITABLE",
                "only an outgoing message can be prepared for editing",
                false,
            ))));
        }
        let already_current = if matches!(parse_mode, CaptionParseMode::Plain) {
            message.text.as_deref() == Some(args.text.as_str())
        } else {
            let current_html = self
                .backend
                .get_message_html(Some(selected_session), &canonical_chat_id, args.message_id)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
            edit_input_matches(&current_html, &requested)
        };
        if already_current {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                "the requested text already matches the current Telegram message",
                false,
            ))));
        }
        let action = MutationAction::EditMessage {
            chat_id: canonical_chat_id,
            before: mutation_snapshot(&message),
            text: args.text,
            parse_mode,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    async fn capture_deleted_attachment(
        &self,
        selected_session: &std::path::Path,
        account_user_id: i64,
        chat_id: &str,
        message_id: i32,
    ) -> Result<FileSnapshot, ToolFailure> {
        let attachments = self
            .backend
            .list_attachments(Some(selected_session.to_path_buf()), chat_id, message_id)
            .await
            .map_err(ToolFailure::from)?;
        let [attachment] = attachments.as_slice() else {
            return Err(ToolFailure::new(
                "MESSAGE_RESTORE_UNSUPPORTED",
                format!(
                    "message {message_id} in {chat_id} did not expose exactly one downloadable attachment"
                ),
                false,
            ));
        };
        if !attachment.downloadable {
            return Err(ToolFailure::new(
                "MESSAGE_RESTORE_UNSUPPORTED",
                format!("message {message_id} in {chat_id} has a non-downloadable attachment"),
                false,
            ));
        }
        let max_bytes = self.settings.max_download_bytes.min(self.settings.max_upload_bytes);
        if attachment.size_bytes.is_some_and(|size| size > max_bytes) {
            return Err(ToolFailure::new(
                "ATTACHMENT_TOO_LARGE",
                format!(
                    "message {message_id} attachment exceeds the recoverable snapshot limit of {max_bytes} bytes"
                ),
                false,
            ));
        }

        let account_root =
            self.settings.attachment_cache_dir.join(account_cache_key(account_user_id));
        tokio::fs::create_dir_all(&account_root).await.map_err(io_failure)?;
        restrict_private_directory(&account_root).map_err(io_failure)?;
        let capture_directory = account_root.join(format!("delete-recovery-{}", Uuid::new_v4()));
        tokio::fs::create_dir(&capture_directory).await.map_err(io_failure)?;
        restrict_private_directory(&capture_directory).map_err(io_failure)?;
        let file_name = sanitize_file_name(
            attachment.file_name.as_deref().unwrap_or("telegram-deletion-recovery.bin"),
        );
        let temporary = capture_directory.join(file_name);
        let result = async {
            let bytes_written = self
                .backend
                .download_attachment_to(
                    Some(selected_session.to_path_buf()),
                    chat_id,
                    message_id,
                    &temporary,
                    max_bytes,
                )
                .await
                .map_err(ToolFailure::from)?;
            restrict_private_file(&temporary).map_err(io_failure)?;
            if bytes_written > max_bytes {
                return Err(ToolFailure::new(
                    "ATTACHMENT_TOO_LARGE",
                    format!(
                        "message {message_id} download produced {bytes_written} bytes; recoverable maximum is {max_bytes}"
                    ),
                    false,
                ));
            }
            snapshot_managed_file(
                &temporary,
                &self.settings.state_db_path,
                self.settings.max_upload_bytes,
            )
            .await
        }
        .await;
        let _ = tokio::fs::remove_dir_all(&capture_directory).await;
        result
    }

    async fn capture_deleted_message_restore_snapshot(
        &self,
        selected_session: &std::path::Path,
        account_user_id: i64,
        chat_id: &str,
        message: &MessageSummary,
    ) -> Result<(DeletedMessageRestoreSnapshot, Option<FileSnapshot>), ToolFailure> {
        let body_html = self
            .backend
            .get_message_html(Some(selected_session.to_path_buf()), chat_id, message.message_id)
            .await
            .map_err(ToolFailure::from)?;
        let topic_id = self
            .backend
            .get_message_topic_id(Some(selected_session.to_path_buf()), chat_id, message.message_id)
            .await
            .map_err(ToolFailure::from)?;
        let grouped_id = self
            .backend
            .get_message_grouped_id(
                Some(selected_session.to_path_buf()),
                chat_id,
                message.message_id,
            )
            .await
            .map_err(ToolFailure::from)?;

        let Some(media_type) = message.media_type.as_deref() else {
            if body_html.is_empty() {
                return Err(ToolFailure::new(
                    "MESSAGE_RESTORE_UNSUPPORTED",
                    format!(
                        "message {} in {chat_id} has neither recoverable text nor media",
                        message.message_id
                    ),
                    false,
                ));
            }
            return Ok((
                DeletedMessageRestoreSnapshot {
                    body_html,
                    topic_id,
                    grouped_id: None,
                    media: None,
                },
                None,
            ));
        };

        if !matches!(media_type, "photo" | "video" | "document" | "gif" | "voice" | "video_note") {
            return Err(ToolFailure::new(
                "MESSAGE_RESTORE_UNSUPPORTED",
                format!(
                    "message {} in {chat_id} uses unsupported Telegram media type {media_type}",
                    message.message_id
                ),
                false,
            ));
        }

        let snapshot = self
            .capture_deleted_attachment(
                selected_session,
                account_user_id,
                chat_id,
                message.message_id,
            )
            .await?;
        let artifact = mutation_file_artifact(&snapshot);
        let media = match media_type {
            "photo" => DeletedMessageRestoreMedia::File {
                artifact,
                mode: FileSendMode::Photo,
                expected_media_type: "photo".to_string(),
                album_media_kind: Some(AlbumMediaKind::Photo),
            },
            "video" => DeletedMessageRestoreMedia::File {
                artifact,
                mode: FileSendMode::Auto,
                expected_media_type: "video".to_string(),
                album_media_kind: Some(AlbumMediaKind::Video),
            },
            "document" => DeletedMessageRestoreMedia::File {
                artifact,
                mode: FileSendMode::Document,
                expected_media_type: "document".to_string(),
                album_media_kind: None,
            },
            "gif" => DeletedMessageRestoreMedia::File {
                artifact,
                mode: FileSendMode::Gif,
                expected_media_type: "gif".to_string(),
                album_media_kind: None,
            },
            "voice" => DeletedMessageRestoreMedia::Voice { artifact },
            "video_note" => {
                let document = self
                    .backend
                    .get_message_document_media(
                        Some(selected_session.to_path_buf()),
                        chat_id,
                        message.message_id,
                    )
                    .await
                    .map_err(ToolFailure::from)?
                    .ok_or_else(|| {
                        ToolFailure::new(
                            "MESSAGE_RESTORE_UNSUPPORTED",
                            format!(
                                "video note {} in {chat_id} has no recoverable document metadata",
                                message.message_id
                            ),
                            false,
                        )
                    })?;
                let duration_seconds = document.duration_seconds.filter(|value| *value > 0);
                let length_pixels = document
                    .width_px
                    .zip(document.height_px)
                    .filter(|(width, height)| width == height && *width > 0)
                    .map(|(width, _)| width);
                let (Some(duration_seconds), Some(length_pixels)) =
                    (duration_seconds, length_pixels)
                else {
                    let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
                    return Err(ToolFailure::new(
                        "MESSAGE_RESTORE_UNSUPPORTED",
                        format!(
                            "video note {} in {chat_id} has incomplete duration or square-size metadata",
                            message.message_id
                        ),
                        false,
                    ));
                };
                DeletedMessageRestoreMedia::VideoNote { artifact, duration_seconds, length_pixels }
            },
            unsupported => {
                let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
                return Err(ToolFailure::new(
                    "MESSAGE_RESTORE_UNSUPPORTED",
                    format!(
                        "message {} in {chat_id} uses unsupported Telegram media type {unsupported}",
                        message.message_id
                    ),
                    false,
                ));
            },
        };
        if grouped_id.is_some()
            && !matches!(&media, DeletedMessageRestoreMedia::File { album_media_kind: Some(_), .. })
        {
            let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
            return Err(ToolFailure::new(
                "MESSAGE_RESTORE_UNSUPPORTED",
                format!(
                    "grouped message {} in {chat_id} is not a recoverable photo/video album item",
                    message.message_id
                ),
                false,
            ));
        }
        Ok((
            DeletedMessageRestoreSnapshot { body_html, topic_id, grouped_id, media: Some(media) },
            Some(snapshot),
        ))
    }

    /// Prepare an immutable deletion bound to exact current Telegram message snapshots.
    #[tool(annotations(
        title = "Prepare Telegram message deletion",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn prepare_delete_messages(
        &self,
        Parameters(args): Parameters<PrepareDeleteMessagesArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_delete_messages")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_ids.is_empty() || args.message_ids.len() > MAX_DELETE_MESSAGES {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "prepare_delete_messages.message_ids must contain 1..={MAX_DELETE_MESSAGES} ids"
            )))));
        }
        let mut seen = HashSet::with_capacity(args.message_ids.len());
        for message_id in &args.message_ids {
            if *message_id <= 0 {
                return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                    "prepare_delete_messages.message_ids must all be positive",
                ))));
            }
            if !seen.insert(*message_id) {
                return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                    "prepare_delete_messages.message_ids must not contain duplicates",
                ))));
            }
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let mut messages = Vec::with_capacity(args.message_ids.len());
        let mut captured_snapshots = Vec::new();
        for message_id in args.message_ids {
            let message = self
                .backend
                .get_message(Some(selected_session.clone()), &canonical_chat_id, message_id)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .ok_or_else(|| {
                    Json(ToolOutcome::failure(ToolFailure::new(
                        "MESSAGE_NOT_FOUND",
                        format!("message {message_id} was not found in {canonical_chat_id}"),
                        false,
                    )))
                })?;
            let mut message_snapshot = mutation_snapshot(&message);
            match self
                .capture_deleted_message_restore_snapshot(
                    &selected_session,
                    account.user_id,
                    &canonical_chat_id,
                    &message,
                )
                .await
            {
                Ok((restore, snapshot)) => {
                    message_snapshot.restore = Some(restore);
                    if let Some(snapshot) = snapshot {
                        captured_snapshots.push(snapshot);
                    }
                },
                Err(error)
                    if args.allow_irrecoverable
                        && matches!(
                            error.code.as_str(),
                            "MESSAGE_RESTORE_UNSUPPORTED" | "ATTACHMENT_TOO_LARGE"
                        ) => {},
                Err(error) => {
                    cleanup_snapshots(&captured_snapshots).await;
                    return Err(Json(ToolOutcome::failure(error)));
                },
            }
            messages.push(message_snapshot);
        }
        let action = MutationAction::DeleteMessages {
            chat_id: canonical_chat_id,
            messages,
            revoke: args.revoke,
        };
        let prepared = prepare_captured_album_mutation(
            &self.mutation_ledger,
            account.user_id,
            action,
            &captured_snapshots,
        )
        .await
        .map_err(|error| Json(ToolOutcome::failure(error)))?;
        Ok(Json(ToolOutcome::success(prepared)))
    }

    /// Prepare recreation of exact deleted-message content from a prior applied deletion snapshot.
    #[tool(annotations(
        title = "Prepare deleted Telegram message restoration",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_restore_deleted_messages(
        &self,
        Parameters(args): Parameters<PrepareRestoreDeletedMessagesArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        let deletion_approval_id = args.deletion_approval_id.trim();
        if deletion_approval_id.is_empty() {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_restore_deleted_messages.deletion_approval_id must not be empty",
            ))));
        }
        if args.message_ids.is_empty() || args.message_ids.len() > MAX_DELETE_MESSAGES {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "prepare_restore_deleted_messages.message_ids must contain 1..={MAX_DELETE_MESSAGES} ids"
            )))));
        }
        let mut selected_ids = args.message_ids;
        selected_ids.sort_unstable();
        if selected_ids.first().is_some_and(|message_id| *message_id <= 0)
            || selected_ids.windows(2).any(|pair| {
                pair.first().zip(pair.get(1)).is_some_and(|(left, right)| left == right)
            })
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_restore_deleted_messages.message_ids must contain unique positive ids",
            ))));
        }

        let source = self
            .mutation_ledger
            .get_approval(deletion_approval_id)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "DELETION_APPROVAL_NOT_FOUND",
                    format!("deletion approval {deletion_approval_id} was not found"),
                    false,
                )))
            })?;
        if source.state != MutationApprovalState::Applied {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "DELETION_NOT_APPLIED",
                format!(
                    "deletion approval {deletion_approval_id} is {:?}, not applied",
                    source.state
                ),
                false,
            ))));
        }
        let MutationAction::DeleteMessages { chat_id, messages, .. } = source.action else {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NOT_A_MESSAGE_DELETION",
                format!("approval {deletion_approval_id} is not a message deletion"),
                false,
            ))));
        };
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        if account.user_id != source.account_user_id {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "ACCOUNT_MISMATCH",
                format!(
                    "deletion belongs to Telegram account {}, but the selected session is {}",
                    source.account_user_id, account.user_id
                ),
                false,
            ))));
        }

        let mut selected_messages = Vec::with_capacity(selected_ids.len());
        for message_id in selected_ids {
            let message = messages
                .iter()
                .find(|message| message.message_id == message_id)
                .cloned()
                .ok_or_else(|| {
                    Json(ToolOutcome::failure(ToolFailure::new(
                        "MESSAGE_NOT_IN_DELETION",
                        format!(
                            "message {message_id} was not part of deletion {deletion_approval_id}"
                        ),
                        false,
                    )))
                })?;
            if message.restore.is_none() {
                return Err(Json(ToolOutcome::failure(ToolFailure::new(
                    "RESTORE_SNAPSHOT_UNAVAILABLE",
                    format!(
                        "message {message_id} was deleted without a recoverable snapshot; Telegram cannot restore the original object"
                    ),
                    false,
                ))));
            }
            if !message.outgoing && !args.allow_sender_change {
                return Err(Json(ToolOutcome::failure(ToolFailure::new(
                    "RESTORE_SENDER_CHANGE_REQUIRES_OPT_IN",
                    format!(
                        "message {message_id} was authored by {}; recreating it from account {} requires allow_sender_change=true",
                        message.sender_ref.as_deref().unwrap_or("an unknown sender"),
                        account.user_id
                    ),
                    false,
                ))));
            }
            if self
                .backend
                .get_message(Some(selected_session.clone()), &chat_id, message_id)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .is_some()
            {
                return Err(Json(ToolOutcome::failure(ToolFailure::new(
                    "MESSAGE_STILL_EXISTS",
                    format!(
                        "message {message_id} still exists in {chat_id}; restoration would duplicate it"
                    ),
                    false,
                ))));
            }
            selected_messages.push(message);
        }
        let random_ids = selected_messages
            .iter()
            .map(|message| restore_random_id(deletion_approval_id, message.message_id))
            .collect::<Vec<_>>();
        let action = MutationAction::RestoreDeletedMessages {
            source_deletion_approval_id: deletion_approval_id.to_string(),
            chat_id,
            messages: selected_messages,
            allow_sender_change: args.allow_sender_change,
            random_ids,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare an exact pin or unpin operation for one current Telegram message.
    #[tool(annotations(
        title = "Prepare Telegram message pin state",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn prepare_set_message_pinned(
        &self,
        Parameters(args): Parameters<PrepareSetMessagePinnedArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_set_message_pinned")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_id <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_set_message_pinned.message_id must be positive",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let message = self
            .backend
            .get_message(Some(selected_session), &canonical_chat_id, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "MESSAGE_NOT_FOUND",
                    format!("message {} was not found in {}", args.message_id, canonical_chat_id),
                    false,
                )))
            })?;
        if message.pinned == args.pinned {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!("message {} already has pinned={}", args.message_id, args.pinned),
                false,
            ))));
        }
        let action = MutationAction::SetMessagePinned {
            chat_id: canonical_chat_id,
            before: mutation_snapshot(&message),
            pinned: args.pinned,
            silent: args.silent,
            one_sided: args.one_sided,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare an exact regular emoji/custom emoji reaction change or removal.
    #[tool(annotations(
        title = "Prepare Telegram message reaction",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn prepare_set_message_reaction(
        &self,
        Parameters(args): Parameters<PrepareSetMessageReactionArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.chat_id, "prepare_set_message_reaction")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_id <= 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_set_message_reaction.message_id must be positive",
            ))));
        }
        validate_reaction_spec(&args.reaction)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let message = self
            .backend
            .get_message(Some(selected_session.clone()), &canonical_chat_id, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "MESSAGE_NOT_FOUND",
                    format!("message {} was not found in {canonical_chat_id}", args.message_id),
                    false,
                )))
            })?;
        let before_reaction = self
            .backend
            .get_my_reaction(Some(selected_session), &canonical_chat_id, args.message_id)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let target_reaction = reaction_target_state(&args.reaction);
        if reaction_states_equal(before_reaction.as_ref(), target_reaction.as_ref()) {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!("message {} already has the requested reaction state", args.message_id),
                false,
            ))));
        }
        let action = MutationAction::SetMessageReaction {
            chat_id: canonical_chat_id,
            before: mutation_snapshot(&message),
            before_reaction,
            reaction: args.reaction,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

