    /// Prepare blocking or unblocking one exact Telegram user.
    #[tool(annotations(
        title = "Prepare Telegram user block state",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_set_user_blocked(
        &self,
        Parameters(args): Parameters<PrepareSetUserBlockedArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_user_ref(&args.user_ref, "prepare_set_user_blocked")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let user = self
            .backend
            .get_user_info(Some(selected_session), &args.user_ref.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        if user.user.user_id == account.user_id {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "the authenticated Telegram account cannot block itself",
            ))));
        }
        if user.blocked == args.blocked {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!("user {} already has blocked={}", user.user.user_id, args.blocked),
                false,
            ))));
        }
        let action = MutationAction::SetUserBlocked {
            user: user.user,
            before_blocked: user.blocked,
            blocked: args.blocked,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare adding or deleting one Telegram contact.
    #[tool(annotations(
        title = "Prepare Telegram contact state",
        read_only_hint = false,
        destructive_hint = true,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_set_contact(
        &self,
        Parameters(args): Parameters<PrepareSetContactArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_user_ref(&args.user_ref, "prepare_set_contact")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if !args.contact
            && (args.first_name.is_some()
                || args.last_name.is_some()
                || args.phone.is_some()
                || args.add_phone_privacy_exception)
        {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "contact metadata is only valid when contact=true",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let details = self
            .backend
            .get_user_info(Some(selected_session), &args.user_ref.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        if details.user.user_id == account.user_id {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "the authenticated Telegram account cannot be added as its own contact",
            ))));
        }
        if details.user.is_contact == args.contact {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "NO_CHANGE",
                format!("user {} already has is_contact={}", details.user.user_id, args.contact),
                false,
            ))));
        }
        let first_name = if args.contact {
            args.first_name.unwrap_or_else(|| details.user.first_name.clone())
        } else {
            details.user.first_name.clone()
        };
        let last_name = if args.contact {
            args.last_name.or_else(|| details.user.last_name.clone()).unwrap_or_default()
        } else {
            details.user.last_name.clone().unwrap_or_default()
        };
        let phone = if args.contact {
            args.phone.or_else(|| details.user.phone.clone()).unwrap_or_default()
        } else {
            String::new()
        };
        validate_contact_fields(&first_name, &last_name, &phone)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let action = MutationAction::SetContact {
            before: details.user,
            contact: args.contact,
            first_name,
            last_name,
            phone,
            add_phone_privacy_exception: args.add_phone_privacy_exception,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

    /// Prepare terminating one non-current Telegram authorization.
    #[tool(annotations(
        title = "Prepare Telegram session termination",
        read_only_hint = false,
        destructive_hint = true,
        idempotent_hint = true,
        open_world_hint = true
    ))]
    async fn prepare_terminate_session(
        &self,
        Parameters(args): Parameters<PrepareTerminateSessionArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        if args.authorization_id == 0 {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                "prepare_terminate_session.authorization_id must not be zero",
            ))));
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let sessions = self
            .backend
            .get_sessions(Some(selected_session))
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        validate_session_state(&sessions, "Telegram authorization sessions")
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let before = sessions
            .into_iter()
            .find(|session| session.authorization_id == args.authorization_id)
            .ok_or_else(|| {
                Json(ToolOutcome::failure(ToolFailure::new(
                    "SESSION_NOT_FOUND",
                    format!("authorization {} was not found", args.authorization_id),
                    false,
                )))
            })?;
        if before.current {
            return Err(Json(ToolOutcome::failure(ToolFailure::new(
                "CURRENT_SESSION_PROTECTED",
                "the active MCP Telegram authorization cannot terminate itself",
                false,
            ))));
        }
        let action = MutationAction::TerminateSession { before };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

