    /// Prepare an exact forward or attribution-stripped copy of current Telegram messages.
    #[tool(annotations(
        title = "Prepare Telegram message forwarding",
        read_only_hint = false,
        destructive_hint = false,
        idempotent_hint = false,
        open_world_hint = true
    ))]
    async fn prepare_forward_messages(
        &self,
        Parameters(args): Parameters<PrepareForwardMessagesArgs>,
    ) -> Result<Json<ToolOutcome<PreparedMutation>>, Json<ToolOutcome<PreparedMutation>>> {
        validate_chat_id(&args.source_chat_id, "prepare_forward_messages.source")
            .and_then(|()| {
                validate_chat_id(&args.destination_chat_id, "prepare_forward_messages.destination")
            })
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        if args.message_ids.is_empty() || args.message_ids.len() > MAX_FORWARD_MESSAGES {
            return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(format!(
                "prepare_forward_messages.message_ids must contain 1..={MAX_FORWARD_MESSAGES} ids"
            )))));
        }
        let mut seen = HashSet::with_capacity(args.message_ids.len());
        for message_id in &args.message_ids {
            if *message_id <= 0 {
                return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                    "prepare_forward_messages.message_ids must all be positive",
                ))));
            }
            if !seen.insert(*message_id) {
                return Err(Json(ToolOutcome::failure(ToolFailure::invalid_argument(
                    "prepare_forward_messages.message_ids must not contain duplicates",
                ))));
            }
        }
        let (account, selected_session) = self
            .backend
            .get_me(None)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let source_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.source_chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let destination_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.destination_chat_id.0)
            .await
            .map_err(|error| Json(ToolOutcome::failure(error.into())))?;
        let mut messages = Vec::with_capacity(args.message_ids.len());
        for message_id in args.message_ids {
            let message = self
                .backend
                .get_message(Some(selected_session.clone()), &source_chat_id, message_id)
                .await
                .map_err(|error| Json(ToolOutcome::failure(error.into())))?
                .ok_or_else(|| {
                    Json(ToolOutcome::failure(ToolFailure::new(
                        "MESSAGE_NOT_FOUND",
                        format!("message {message_id} was not found in {source_chat_id}"),
                        false,
                    )))
                })?;
            messages.push(mutation_snapshot(&message));
        }
        let random_ids = (0..messages.len()).map(|_| new_random_id()).collect::<Vec<_>>();
        let action = MutationAction::ForwardMessages {
            source_chat_id,
            messages,
            destination_chat_id,
            silent: args.silent,
            drop_author: args.drop_author,
            drop_media_captions: args.drop_media_captions,
            noforwards: args.noforwards,
            random_ids,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)
            .map_err(|error| Json(ToolOutcome::failure(error)))?;
        let prepared = self
            .mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map_err(|error| Json(ToolOutcome::failure(ledger_failure(error))))?;
        Ok(Json(ToolOutcome::success(prepared.public)))
    }

