    async fn prepare_revoke_invite_link_mutation(
        &self,
        chat_id: &ChatId,
        admin_id: Option<&UserRef>,
        invite_handle: &str,
    ) -> Result<PreparedMutation, ToolFailure> {
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let admin_user_id = self
            .resolve_invite_admin_user_id(
                &selected_session,
                account.user_id,
                admin_id,
                "revoke_invite_link.admin_id",
            )
            .await?;
        let before = self
            .backend
            .get_invite_link(
                Some(selected_session),
                &canonical_chat_id,
                admin_user_id,
                invite_handle,
            )
            .await
            .map_err(ToolFailure::from)?
            .ok_or_else(|| {
                ToolFailure::new(
                    "INVITE_LINK_NOT_FOUND",
                    "the opaque invite handle was not found for this chat",
                    false,
                )
            })?;
        if before.kind != InviteLinkKind::Exported {
            return Err(ToolFailure::invalid_argument(
                "public join-request routing cannot be revoked as an exported invite link",
            ));
        }
        if before.revoked {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                "the selected invite link is already revoked",
                false,
            ));
        }
        let action = MutationAction::RevokeInviteLink { chat_id: canonical_chat_id, before };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

