    async fn read_bot_command_state(
        &self,
        bot_ref: &UserRef,
        language_code: &str,
    ) -> Result<BotCommandSetSummary, ToolFailure> {
        validate_user_ref(bot_ref, "bot")?;
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let details = self
            .backend
            .get_user_info(Some(selected_session.clone()), &bot_ref.0)
            .await
            .map_err(ToolFailure::from)?;
        if !details.user.bot {
            return Err(ToolFailure::new(
                "BOT_ACCOUNT_REQUIRED",
                "the bound Telegram identity is not a bot account",
                false,
            ));
        }
        if details.user.user_id != account.user_id {
            return Err(ToolFailure::new(
                "BOT_ACCOUNT_MISMATCH",
                format!(
                    "bot resolves to Telegram user {}, but the authenticated account is {}",
                    details.user.user_id, account.user_id
                ),
                false,
            ));
        }
        let commands = self
            .backend
            .get_bot_commands(Some(selected_session), language_code)
            .await
            .map_err(ToolFailure::from)?;
        validate_bot_commands(&commands).map_err(|error| {
            ToolFailure::new(
                "STATE_INTEGRITY_ERROR",
                format!("Telegram returned an invalid bot command set: {}", error.message),
                false,
            )
        })?;
        Ok(BotCommandSetSummary {
            bot: details.user,
            language_code: language_code.to_string(),
            commands,
        })
    }

