    async fn prepare_set_personal_channel_mutation(
        &self,
        channel_id: Option<ChatId>,
    ) -> Result<PreparedMutation, ToolFailure> {
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let profile = self
            .backend
            .get_account_profile(Some(selected_session.clone()))
            .await
            .map_err(ToolFailure::from)?;
        ensure_account_profile_identity(&profile, account.user_id)?;
        if let Some(before) = profile.personal_channel.as_ref() {
            validate_personal_channel_summary(before, "Telegram personal channel")?;
        }
        let channel = if let Some(channel_id) = channel_id {
            let canonical_chat_id = self
                .backend
                .resolve_chat_id(Some(selected_session.clone()), &channel_id.0)
                .await
                .map_err(ToolFailure::from)?;
            validate_personal_channel_id(&canonical_chat_id, "set_personal_channel.channel_id")?;
            let state = self
                .backend
                .get_chat_lifecycle_state(Some(selected_session), &canonical_chat_id)
                .await
                .map_err(ToolFailure::from)?;
            validate_personal_channel_chat(&state.details.chat, "set_personal_channel.channel_id")?;
            Some(state.details.chat)
        } else {
            None
        };
        if personal_channel_matches_target(profile.personal_channel.as_ref(), channel.as_ref()) {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                if channel.is_some() {
                    "the account already features the requested personal channel"
                } else {
                    "the account has no personal channel to clear"
                },
                false,
            ));
        }
        let action =
            MutationAction::SetAccountPersonalChannel { before: profile.personal_channel, channel };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

