    async fn prepare_reorder_dialog_folders_mutation(
        &self,
        target_order: Vec<i32>,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_folder_order(&target_order)?;
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let folders = self
            .backend
            .list_dialog_folders(Some(selected_session))
            .await
            .map_err(ToolFailure::from)?;
        let before_order = non_default_folder_order(&folders);
        if before_order.iter().copied().collect::<HashSet<_>>()
            != target_order.iter().copied().collect::<HashSet<_>>()
            || before_order.len() != target_order.len()
        {
            return Err(ToolFailure::invalid_argument(
                "reorder_folders.folder_ids must be an exact permutation of every non-default folder id",
            ));
        }
        if before_order == target_order {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                "dialog folders already have the requested order",
                false,
            ));
        }
        let action = MutationAction::ReorderDialogFolders { before_order, target_order };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

