    async fn prepare_set_global_privacy_settings_mutation(
        &self,
        args: SetGlobalPrivacySettingsArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        let has_patch = args.archive_and_mute_new_noncontact_peers.is_some()
            || args.keep_archived_unmuted.is_some()
            || args.keep_archived_folders.is_some()
            || args.hide_read_marks.is_some()
            || args.new_noncontact_peers_require_premium.is_some()
            || args.display_gifts_button.is_some()
            || args.noncontact_peers_paid_stars.is_some()
            || args.clear_noncontact_peers_paid_stars
            || args.disallowed_gifts.is_some()
            || args.clear_disallowed_gifts;
        if !has_patch {
            return Err(ToolFailure::invalid_argument(
                "set_global_privacy_settings requires at least one setting",
            ));
        }
        if args.noncontact_peers_paid_stars.is_some() && args.clear_noncontact_peers_paid_stars {
            return Err(ToolFailure::invalid_argument(
                "set_global_privacy_settings cannot set and clear noncontact_peers_paid_stars together",
            ));
        }
        if args.disallowed_gifts.is_some() && args.clear_disallowed_gifts {
            return Err(ToolFailure::invalid_argument(
                "set_global_privacy_settings cannot set and clear disallowed_gifts together",
            ));
        }
        if let Some(stars) = args.noncontact_peers_paid_stars.as_deref() {
            parse_positive_i64(stars, "set_global_privacy_settings.noncontact_peers_paid_stars")?;
        }

        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let before = self
            .backend
            .get_global_privacy_settings(Some(selected_session))
            .await
            .map_err(ToolFailure::from)?;
        validate_global_privacy_settings_summary(&before, "Telegram global privacy settings")?;
        let target = GlobalPrivacySettingsSummary {
            archive_and_mute_new_noncontact_peers: args
                .archive_and_mute_new_noncontact_peers
                .unwrap_or(before.archive_and_mute_new_noncontact_peers),
            keep_archived_unmuted: args
                .keep_archived_unmuted
                .unwrap_or(before.keep_archived_unmuted),
            keep_archived_folders: args
                .keep_archived_folders
                .unwrap_or(before.keep_archived_folders),
            hide_read_marks: args.hide_read_marks.unwrap_or(before.hide_read_marks),
            new_noncontact_peers_require_premium: args
                .new_noncontact_peers_require_premium
                .unwrap_or(before.new_noncontact_peers_require_premium),
            display_gifts_button: args.display_gifts_button.unwrap_or(before.display_gifts_button),
            noncontact_peers_paid_stars: if args.clear_noncontact_peers_paid_stars {
                None
            } else {
                args.noncontact_peers_paid_stars
                    .or_else(|| before.noncontact_peers_paid_stars.clone())
            },
            disallowed_gifts: if args.clear_disallowed_gifts {
                None
            } else {
                args.disallowed_gifts
                    .map(DisallowedGiftsSettingsSummary::from)
                    .or_else(|| before.disallowed_gifts.clone())
            },
        };
        validate_global_privacy_settings_summary(&target, "target global privacy settings")?;
        if target == before {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                "the account already has the requested global privacy settings",
                false,
            ));
        }
        let action = MutationAction::SetGlobalPrivacySettings { before, target };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

    async fn prepare_create_group_mutation(
        &self,
        args: CreateGroupArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        let title = normalize_chat_title(&args.title, "create_group.title")?;
        if args.user_refs.is_empty() || args.user_refs.len() > MAX_CREATE_GROUP_USERS {
            return Err(ToolFailure::invalid_argument(format!(
                "create_group.user_refs must contain 1..={MAX_CREATE_GROUP_USERS} users"
            )));
        }
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let mut users = Vec::with_capacity(args.user_refs.len());
        let mut seen = HashSet::with_capacity(args.user_refs.len());
        for user_ref in args.user_refs {
            validate_user_ref(&user_ref, "create_group.user_refs")?;
            let user = self
                .backend
                .get_user_info(Some(selected_session.clone()), &user_ref.0)
                .await
                .map_err(ToolFailure::from)?
                .user;
            if user.user_id == account.user_id {
                return Err(ToolFailure::invalid_argument(
                    "create_group.user_refs must not include the authenticated account",
                ));
            }
            if !seen.insert(user.user_id) {
                return Err(ToolFailure::invalid_argument(format!(
                    "create_group.user_refs resolves user {} more than once",
                    user.user_id
                )));
            }
            users.push(user);
        }
        let action = MutationAction::CreateGroup { title, users };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

