    async fn prepare_toggle_chat_forum_mutation(
        &self,
        args: ToggleChatForumModeArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(&args.chat_id, "toggle_forum_mode")?;
        if !args.enabled && !args.confirm_disable {
            return Err(ToolFailure::invalid_argument(
                "toggle_forum_mode.confirm_disable must be true when disabling because Telegram removes all existing topics",
            ));
        }
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let before = self
            .backend
            .get_chat_moderation_settings(Some(selected_session), &canonical_chat_id)
            .await
            .map_err(ToolFailure::from)?;
        let current = before.forum_enabled.ok_or_else(|| {
            ToolFailure::invalid_argument(
                "toggle_forum_mode requires a supergroup, not a basic group or broadcast channel",
            )
        })?;
        let current_tabs = before.forum_tabs_enabled.unwrap_or(false);
        let tabs_enabled = args.enabled && args.tabs_enabled.unwrap_or(current_tabs);
        if current == args.enabled && current_tabs == tabs_enabled {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                format!("supergroup {canonical_chat_id} already has the requested forum state"),
                false,
            ));
        }
        let action =
            MutationAction::ToggleChatForum { before, enabled: args.enabled, tabs_enabled };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

    async fn prepare_view_story_mutation(
        &self,
        args: ViewStoryArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(&args.chat_id, "view_story")?;
        validate_story_ids(&args.story_ids, "view_story")?;
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let page = self
            .backend
            .get_peer_stories(Some(selected_session), &canonical_chat_id)
            .await
            .map_err(ToolFailure::from)?;
        let mut before = Vec::with_capacity(args.story_ids.len());
        for story_id in &args.story_ids {
            let story =
                page.peer.stories.iter().find(|story| story.story_id == *story_id).ok_or_else(
                    || {
                        ToolFailure::new(
                            "STORY_NOT_FOUND",
                            format!("story {story_id} was not found for {}", page.peer.peer_ref),
                            false,
                        )
                    },
                )?;
            if story.state == "deleted" {
                return Err(ToolFailure::new(
                    "STORY_NOT_FOUND",
                    format!("story {story_id} is deleted for {}", page.peer.peer_ref),
                    false,
                ));
            }
            before.push(story_mutation_snapshot(story));
        }
        let action = MutationAction::ViewStories {
            peer_ref: page.peer.peer_ref,
            before,
            story_ids: args.story_ids,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

    async fn prepare_read_stories_mutation(
        &self,
        args: ReadStoriesArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(&args.chat_id, "read_stories")?;
        if args.max_id <= 0 {
            return Err(ToolFailure::invalid_argument("read_stories.max_id must be positive"));
        }
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let page = self
            .backend
            .get_peer_stories(Some(selected_session), &canonical_chat_id)
            .await
            .map_err(ToolFailure::from)?;
        if page.peer.max_read_id.is_some_and(|current| current >= args.max_id) {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                format!(
                    "stories for {} are already read through {}",
                    page.peer.peer_ref, args.max_id
                ),
                false,
            ));
        }
        let target = page
            .peer
            .stories
            .iter()
            .find(|story| story.story_id == args.max_id && story.state != "deleted")
            .map(story_mutation_snapshot)
            .ok_or_else(|| {
                ToolFailure::new(
                    "STORY_NOT_FOUND",
                    format!("story {} was not found for {}", args.max_id, page.peer.peer_ref),
                    false,
                )
            })?;
        let action = MutationAction::ReadStories {
            peer_ref: page.peer.peer_ref,
            before_max_read_id: page.peer.max_read_id,
            target,
            max_id: args.max_id,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

    async fn prepare_story_reaction_mutation(
        &self,
        args: ReactToStoryArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(&args.chat_id, "react_to_story")?;
        if args.story_id <= 0 {
            return Err(ToolFailure::invalid_argument("react_to_story.story_id must be positive"));
        }
        validate_reaction_spec(&args.reaction)?;
        if matches!(
            &args.reaction,
            ReactionSpec::Emoji { big: true, .. } | ReactionSpec::CustomEmoji { big: true, .. }
        ) {
            return Err(ToolFailure::invalid_argument(
                "react_to_story.reaction.big is not supported by Telegram stories",
            ));
        }
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let story = self
            .backend
            .get_story(Some(selected_session), &canonical_chat_id, args.story_id)
            .await
            .map_err(ToolFailure::from)?
            .filter(|story| story.state != "deleted")
            .ok_or_else(|| {
                ToolFailure::new(
                    "STORY_NOT_FOUND",
                    format!("story {} was not found for {canonical_chat_id}", args.story_id),
                    false,
                )
            })?;
        if reaction_states_equal(
            story.sent_reaction.as_ref(),
            story_reaction_target(&args.reaction).as_ref(),
        ) {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                format!("story {} already has the requested reaction", args.story_id),
                false,
            ));
        }
        let action = MutationAction::SetStoryReaction {
            peer_ref: canonical_chat_id,
            before: StoryReactionSnapshot {
                story: story_mutation_snapshot(&story),
                sent_reaction: story.sent_reaction,
            },
            reaction: args.reaction,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

    async fn prepare_stories_pinned_mutation(
        &self,
        args: SetStoriesPinnedArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(&args.chat_id, "toggle_story_pinned")?;
        validate_story_ids(&args.story_ids, "toggle_story_pinned")?;
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let page = self
            .backend
            .get_stories_by_ids(Some(selected_session), &canonical_chat_id, &args.story_ids)
            .await
            .map_err(ToolFailure::from)?;
        let mut before = Vec::with_capacity(args.story_ids.len());
        for story_id in &args.story_ids {
            let story = page
                .stories
                .iter()
                .find(|story| story.story_id == *story_id && story.state != "deleted")
                .ok_or_else(|| {
                    ToolFailure::new(
                        "STORY_NOT_FOUND",
                        format!("story {story_id} was not found for {}", page.peer_ref),
                        false,
                    )
                })?;
            before.push(StoryPinSnapshot {
                story: story_mutation_snapshot(story),
                pinned: story.pinned,
            });
        }
        if before.iter().all(|snapshot| snapshot.pinned == args.pinned) {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                format!("all selected stories already have pinned={}", args.pinned),
                false,
            ));
        }
        let action = MutationAction::SetStoriesPinned {
            peer_ref: page.peer_ref,
            before,
            story_ids: args.story_ids,
            pinned: args.pinned,
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

