    async fn resolve_story_privacy_spec(
        &self,
        selected_session: &Path,
        account_user_id: i64,
        privacy: &str,
        selected_user_refs: Vec<UserRef>,
        disallowed_user_refs: Vec<UserRef>,
        tool_name: &str,
    ) -> Result<StoryPrivacySpec, ToolFailure> {
        let privacy_kind = match privacy.trim().to_ascii_lowercase().as_str() {
            "selected" => "selected_contacts".to_string(),
            kind @ ("everyone" | "contacts" | "close_friends" | "selected_contacts") => {
                kind.to_string()
            },
            _ => {
                return Err(ToolFailure::invalid_argument(format!(
                    "{tool_name}.privacy must be everyone, contacts, close_friends, selected, or selected_contacts"
                )));
            },
        };
        if privacy_kind == "selected_contacts" {
            if selected_user_refs.is_empty()
                || selected_user_refs.len() > MAX_PRIVACY_RULE_REFERENCES
            {
                return Err(ToolFailure::invalid_argument(format!(
                    "{tool_name}.selected_user_refs must contain 1..={MAX_PRIVACY_RULE_REFERENCES} users for selected_contacts privacy"
                )));
            }
            if !disallowed_user_refs.is_empty() {
                return Err(ToolFailure::invalid_argument(format!(
                    "{tool_name}.disallowed_user_refs is not accepted for selected_contacts privacy"
                )));
            }
        } else if !selected_user_refs.is_empty() {
            return Err(ToolFailure::invalid_argument(format!(
                "{tool_name}.selected_user_refs is accepted only for selected_contacts privacy"
            )));
        }
        if privacy_kind == "close_friends" && !disallowed_user_refs.is_empty() {
            return Err(ToolFailure::invalid_argument(format!(
                "{tool_name}.disallowed_user_refs is accepted only for everyone or contacts privacy"
            )));
        }
        if disallowed_user_refs.len() > MAX_PRIVACY_RULE_REFERENCES {
            return Err(ToolFailure::invalid_argument(format!(
                "{tool_name}.disallowed_user_refs must contain at most {MAX_PRIVACY_RULE_REFERENCES} users"
            )));
        }

        let mut seen_user_ids = HashSet::with_capacity(
            selected_user_refs.len().saturating_add(disallowed_user_refs.len()),
        );
        let mut selected_user_ids = Vec::with_capacity(selected_user_refs.len());
        for user_ref in selected_user_refs {
            validate_user_ref(&user_ref, tool_name)?;
            let details = self
                .backend
                .get_user_info(Some(selected_session.to_path_buf()), &user_ref.0)
                .await
                .map_err(ToolFailure::from)?;
            if details.user.user_id == account_user_id {
                return Err(ToolFailure::invalid_argument(
                    "the authenticated Telegram account cannot be a story privacy recipient",
                ));
            }
            if !seen_user_ids.insert(details.user.user_id) {
                return Err(ToolFailure::invalid_argument(format!(
                    "{tool_name} resolves to duplicate privacy user {}",
                    details.user.user_id
                )));
            }
            selected_user_ids.push(details.user.user_id);
        }
        let mut disallowed_user_ids = Vec::with_capacity(disallowed_user_refs.len());
        for user_ref in disallowed_user_refs {
            validate_user_ref(&user_ref, tool_name)?;
            let details = self
                .backend
                .get_user_info(Some(selected_session.to_path_buf()), &user_ref.0)
                .await
                .map_err(ToolFailure::from)?;
            if details.user.user_id == account_user_id {
                return Err(ToolFailure::invalid_argument(
                    "the authenticated Telegram account cannot be excluded from its own story privacy",
                ));
            }
            if !seen_user_ids.insert(details.user.user_id) {
                return Err(ToolFailure::invalid_argument(format!(
                    "{tool_name} resolves to duplicate or conflicting privacy user {}",
                    details.user.user_id
                )));
            }
            disallowed_user_ids.push(details.user.user_id);
        }
        selected_user_ids.sort_unstable();
        disallowed_user_ids.sort_unstable();
        Ok(StoryPrivacySpec { kind: privacy_kind, selected_user_ids, disallowed_user_ids })
    }

    async fn prepare_send_story_mutation(
        &self,
        args: SendStoryArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(&args.chat_id, "send_story")?;
        if args.caption.encode_utf16().count() > MAX_STORY_CAPTION_UTF16 {
            return Err(ToolFailure::invalid_argument(format!(
                "send_story.caption must be <= {MAX_STORY_CAPTION_UTF16} UTF-16 code units"
            )));
        }
        if args
            .period_seconds
            .is_some_and(|period| !matches!(period, 21_600 | 43_200 | 86_400 | 172_800))
        {
            return Err(ToolFailure::invalid_argument(
                "send_story.period_seconds must be 21600, 43200, 86400, or 172800 when provided",
            ));
        }

        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let before = self
            .backend
            .get_peer_stories(Some(selected_session.clone()), &canonical_chat_id)
            .await
            .map_err(ToolFailure::from)?;

        let privacy = self
            .resolve_story_privacy_spec(
                &selected_session,
                account.user_id,
                &args.privacy,
                args.selected_user_refs,
                args.disallowed_user_refs,
                "send_story",
            )
            .await?;

        let snapshot = capture_approved_upload(
            &args.file_path,
            &args.approved_sha256,
            &self.settings.attachment_cache_dir,
            &self.settings.state_db_path,
            account.user_id,
            self.settings.max_upload_bytes,
            "send_story",
        )
        .await?;
        if let Err(error) = validate_story_media(&snapshot.path).await {
            let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
            return Err(error);
        }
        let artifact = MutationFileArtifact {
            artifact_id: snapshot.artifact_id.clone(),
            file_name: snapshot
                .path
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("story.bin")
                .to_string(),
            size_bytes: snapshot.size_bytes,
            sha256: snapshot.sha256,
        };
        let action = MutationAction::SendStory {
            peer_ref: before.peer.peer_ref,
            before_story_ids: before.peer.stories.into_iter().map(|story| story.story_id).collect(),
            artifact,
            caption: args.caption,
            privacy,
            pinned: args.pinned,
            noforwards: args.noforwards,
            period_seconds: args.period_seconds,
            random_id: new_random_id(),
        };
        let payload_sha256 = match mutation_payload_hash(account.user_id, &action) {
            Ok(hash) => hash,
            Err(error) => {
                let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
                return Err(error);
            },
        };
        match self.mutation_ledger.prepare(account.user_id, action, payload_sha256) {
            Ok(prepared) => Ok(prepared.public),
            Err(error) => {
                let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
                Err(ledger_failure(error))
            },
        }
    }

    async fn prepare_edit_story_mutation(
        &self,
        args: EditStoryArgs,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(&args.chat_id, "edit_story")?;
        if args.story_id <= 0 {
            return Err(ToolFailure::invalid_argument("edit_story.story_id must be positive"));
        }
        if args
            .caption
            .as_deref()
            .is_some_and(|caption| caption.encode_utf16().count() > MAX_STORY_CAPTION_UTF16)
        {
            return Err(ToolFailure::invalid_argument(format!(
                "edit_story.caption must be <= {MAX_STORY_CAPTION_UTF16} UTF-16 code units"
            )));
        }
        if args.file_path.is_some() != args.approved_sha256.is_some() {
            return Err(ToolFailure::invalid_argument(
                "edit_story.file_path and approved_sha256 must be provided together",
            ));
        }
        if args.file_path.is_none() && args.caption.is_none() && args.privacy.is_none() {
            return Err(ToolFailure::invalid_argument(
                "edit_story requires file_path, caption, privacy, or a combination",
            ));
        }
        if args.privacy.is_none()
            && (!args.selected_user_refs.is_empty() || !args.disallowed_user_refs.is_empty())
        {
            return Err(ToolFailure::invalid_argument(
                "edit_story privacy user references require privacy to be provided",
            ));
        }

        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &args.chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let before_story = self
            .backend
            .get_story(Some(selected_session.clone()), &canonical_chat_id, args.story_id)
            .await
            .map_err(ToolFailure::from)?
            .filter(|story| story.state != "deleted")
            .ok_or_else(|| {
                ToolFailure::new(
                    "STORY_NOT_FOUND",
                    format!("story {} was not found for {canonical_chat_id}", args.story_id),
                    false,
                )
            })?;
        let privacy = if let Some(privacy) = args.privacy.as_deref() {
            Some(
                self.resolve_story_privacy_spec(
                    &selected_session,
                    account.user_id,
                    privacy,
                    args.selected_user_refs,
                    args.disallowed_user_refs,
                    "edit_story",
                )
                .await?,
            )
        } else {
            None
        };
        if args.file_path.is_none()
            && story_matches_edit_target(
                &before_story,
                args.caption.as_deref(),
                privacy.as_ref(),
                None,
            )
        {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                format!("story {} already has the requested caption and privacy", args.story_id),
                false,
            ));
        }

        let mut snapshot = None;
        let mut artifact = None;
        let mut target_media_kind = None;
        if let (Some(file_path), Some(approved_sha256)) =
            (args.file_path.as_deref(), args.approved_sha256.as_deref())
        {
            let captured = capture_approved_upload(
                file_path,
                approved_sha256,
                &self.settings.attachment_cache_dir,
                &self.settings.state_db_path,
                account.user_id,
                self.settings.max_upload_bytes,
                "edit_story",
            )
            .await?;
            let media_kind = match validate_story_media(&captured.path).await {
                Ok(media_kind) => media_kind,
                Err(error) => {
                    let _ = tokio::fs::remove_dir_all(&captured.directory).await;
                    return Err(error);
                },
            };
            artifact = Some(MutationFileArtifact {
                artifact_id: captured.artifact_id.clone(),
                file_name: captured
                    .path
                    .file_name()
                    .and_then(|value| value.to_str())
                    .unwrap_or("story.bin")
                    .to_string(),
                size_bytes: captured.size_bytes,
                sha256: captured.sha256.clone(),
            });
            target_media_kind = Some(media_kind);
            snapshot = Some(captured);
        }

        let action = MutationAction::EditStory {
            peer_ref: canonical_chat_id,
            before: story_edit_snapshot(&before_story),
            artifact,
            target_media_kind,
            caption: args.caption,
            privacy,
        };
        let payload_sha256 = match mutation_payload_hash(account.user_id, &action) {
            Ok(hash) => hash,
            Err(error) => {
                if let Some(snapshot) = &snapshot {
                    let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
                }
                return Err(error);
            },
        };
        match self.mutation_ledger.prepare(account.user_id, action, payload_sha256) {
            Ok(prepared) => Ok(prepared.public),
            Err(error) => {
                if let Some(snapshot) = &snapshot {
                    let _ = tokio::fs::remove_dir_all(&snapshot.directory).await;
                }
                Err(ledger_failure(error))
            },
        }
    }

