    async fn prepare_dialog_mutation(
        &self,
        chat_id: &ChatId,
        intent: DialogMutationIntent,
    ) -> Result<PreparedMutation, ToolFailure> {
        validate_chat_id(chat_id, "prepare_dialog_mutation")?;
        let (account, selected_session) =
            self.backend.get_me(None).await.map_err(ToolFailure::from)?;
        let canonical_chat_id = self
            .backend
            .resolve_chat_id(Some(selected_session.clone()), &chat_id.0)
            .await
            .map_err(ToolFailure::from)?;
        let before = self
            .backend
            .get_dialog_state(Some(selected_session), &canonical_chat_id)
            .await
            .map_err(ToolFailure::from)?;
        let already = match intent {
            DialogMutationIntent::Unread(unread) => before.unread_mark == unread,
            DialogMutationIntent::Archived(archived) => before.archived == archived,
            DialogMutationIntent::Pinned(pinned) => before.pinned == pinned,
        };
        if already {
            return Err(ToolFailure::new(
                "NO_CHANGE",
                format!("dialog {canonical_chat_id} already has the requested state"),
                false,
            ));
        }
        let action = match intent {
            DialogMutationIntent::Unread(unread) => {
                MutationAction::SetDialogUnread { chat_id: canonical_chat_id, before, unread }
            },
            DialogMutationIntent::Archived(archived) => {
                MutationAction::SetDialogArchived { chat_id: canonical_chat_id, before, archived }
            },
            DialogMutationIntent::Pinned(pinned) => {
                MutationAction::SetDialogPinned { chat_id: canonical_chat_id, before, pinned }
            },
        };
        let payload_sha256 = mutation_payload_hash(account.user_id, &action)?;
        self.mutation_ledger
            .prepare(account.user_id, action, payload_sha256)
            .map(|prepared| prepared.public)
            .map_err(ledger_failure)
    }

