    #[test]
    fn incoming_event_filter_requires_an_exact_private_human_identity() {
        let human = ContactSummary {
            user_id: 101,
            first_name: "Alex".to_string(),
            last_name: None,
            display_name: "Alex".to_string(),
            username: Some("alex".to_string()),
            phone: None,
            is_contact: true,
            mutual_contact: true,
            bot: false,
            verified: false,
            premium: false,
            scam: false,
            restricted: false,
        };
        let mut bot = human.clone();
        bot.user_id = 102;
        bot.display_name = "Fixture Bot".to_string();
        bot.username = Some("fixture_bot".to_string());
        bot.bot = true;
        let contacts = [&human, &bot]
            .into_iter()
            .map(|contact| (contact.user_id, contact))
            .collect::<HashMap<_, _>>();
        let message = MessageSummary {
            message_id: 11,
            chat_ref: Some("101".to_string()),
            sender_ref: Some("101".to_string()),
            outgoing: false,
            pinned: false,
            silent: false,
            noforwards: false,
            text: Some("hello".to_string()),
            date: 1_700_000_011,
            edit_date: None,
            reply_to_message_id: None,
            views: None,
            forwards: None,
            reply_count: None,
            media_type: None,
            forward_origin: None,
        };

        let event = incoming_event_from_message(&message, &contacts, 7, 1_700_000_011_123)
            .expect("private human event");
        assert_eq!(event.chat_id, "101");
        assert_eq!(event.sender_name, "Alex");
        assert_eq!(event.message_id, 11);

        let mut rejected = message.clone();
        rejected.outgoing = true;
        assert!(incoming_event_from_message(&rejected, &contacts, 7, 1).is_none());
        rejected.outgoing = false;
        rejected.chat_ref = Some("-202".to_string());
        assert!(incoming_event_from_message(&rejected, &contacts, 7, 1).is_none());
        rejected.chat_ref = Some("101".to_string());
        rejected.sender_ref = Some("7".to_string());
        assert!(incoming_event_from_message(&rejected, &contacts, 7, 1).is_none());
        rejected.chat_ref = Some("102".to_string());
        rejected.sender_ref = Some("102".to_string());
        assert!(incoming_event_from_message(&rejected, &contacts, 7, 1).is_none());
        rejected.chat_ref = Some("103".to_string());
        rejected.sender_ref = Some("103".to_string());
        assert!(incoming_event_from_message(&rejected, &contacts, 7, 1).is_none());
    }

    #[test]
    fn settled_bursts_split_on_quiet_gaps_and_keep_interleaved_chats_independent() {
        let event =
            |event_id, chat_id: &str, message_id, observed_at_unix_ms| IncomingMessageEvent {
                event_id,
                chat_id: chat_id.to_string(),
                sender_user_id: chat_id.parse().expect("numeric chat"),
                sender_name: format!("User {chat_id}"),
                sender_username: None,
                message_id,
                message_date_unix: observed_at_unix_ms / 1_000,
                observed_at_unix_ms,
            };
        let events = vec![
            event(1, "101", 10, 1_000),
            event(2, "202", 20, 1_500),
            event(3, "101", 11, 2_000),
            event(4, "101", 12, 9_000),
        ];
        let (first, next) = next_settled_incoming_burst(&events, 6_000, 9_500);
        let first = first.expect("the first Alex burst is closed by a later quiet gap");
        assert_eq!(first.chat_id, "101");
        assert_eq!(first.message_count, 2);
        assert_eq!(first.first_message_id, 10);
        assert_eq!(first.last_message_id, 11);
        assert_eq!(first.burst_seconds, 1.0);
        assert_eq!(next, None);

        let (settled, next) = next_settled_incoming_burst(&events[3..], 6_000, 14_999);
        assert!(settled.is_none());
        assert_eq!(next, Some(15_000));
        let (settled, _) = next_settled_incoming_burst(&events[3..], 6_000, 15_000);
        assert_eq!(settled.expect("quiet boundary is inclusive").last_message_id, 12);
    }

