/// Which live record let a dispatch skip its confirmation card (#1598):
/// the interactive owner grant, or a durable, evidence-backed owner
/// permission exported by orch. Only the label for the log line differs.
enum CoveredBy {
    Grant(crate::approval::OwnerGrantUse),
    Permission(crate::approval::OwnerPermissionLease),
}

/// Durable permissions declare actions by name (`send_message`,
/// `press_callback_button`, …); the mutation action serializes as an
/// internally-tagged variant (`{"kind":"press_callback_button", …}`), so its
/// label is the `kind` value — the vocabulary the owner records use.
fn mutation_action_label(action: &MutationAction) -> String {
    serde_json::to_value(action)
        .ok()
        .and_then(|value| {
            value.get("kind").and_then(serde_json::Value::as_str).map(str::to_string)
        })
        .unwrap_or_default()
}

/// Peer candidates for a mutation: exactly the target peer read from the
/// serialized action (the first peer-shaped field found depth-first). An
/// earlier revision also admitted every allowed grant peer that literally
/// occurred anywhere in the action JSON; containment is not identity — a grant
/// for one peer then authorized a mutation aimed at an unrelated chat (a peer
/// name appearing in a button label or a file name was enough), so the target
/// is now the only candidate and it must match `allow_peers` by normalized
/// identity.
fn mutation_grant_peers(action: &MutationAction) -> Vec<String> {
    mutation_target_peer(action).into_iter().collect()
}

fn mutation_target_peer(action: &MutationAction) -> Option<String> {
    let value = serde_json::to_value(action).ok()?;
    // Actions serialize as nested variants (`{"send_file":{"chat_id":…}}`), so
    // the peer is searched depth-first rather than at the top level only.
    fn search(value: &serde_json::Value, depth: usize) -> Option<String> {
        if depth > 4 {
            return None;
        }
        match value {
            serde_json::Value::Object(map) => {
                for key in ["chat_id", "target_chat_id", "peer_ref", "user_id"] {
                    if let Some(found) = map.get(key).and_then(serde_json::Value::as_str) {
                        if !found.trim().is_empty() {
                            return Some(found.to_string());
                        }
                    }
                    if let Some(found) = map.get(key).and_then(serde_json::Value::as_i64) {
                        return Some(found.to_string());
                    }
                }
                map.values().find_map(|nested| search(nested, depth + 1))
            }
            serde_json::Value::Array(items) => {
                items.iter().find_map(|nested| search(nested, depth + 1))
            }
            _ => None,
        }
    }
    search(&value, 0)
}

/// The chat a mutation card talks about, when the action has one. Unlike
/// `mutation_target_peer`, `user_id` alone never qualifies: a card for a
/// contact-level action must not pretend a user is a chat, and the caller
/// then simply renders no chat line.
fn mutation_chat_peer(action: &MutationAction) -> Option<String> {
    let value = serde_json::to_value(action).ok()?;
    fn search(value: &serde_json::Value, depth: usize) -> Option<String> {
        if depth > 4 {
            return None;
        }
        match value {
            serde_json::Value::Object(map) => {
                for key in ["chat_id", "target_chat_id", "peer_ref"] {
                    if let Some(found) = map.get(key).and_then(serde_json::Value::as_str) {
                        if !found.trim().is_empty() {
                            return Some(found.to_string());
                        }
                    }
                    if let Some(found) = map.get(key).and_then(serde_json::Value::as_i64) {
                        return Some(found.to_string());
                    }
                }
                map.values().find_map(|nested| search(nested, depth + 1))
            }
            serde_json::Value::Array(items) => {
                items.iter().find_map(|nested| search(nested, depth + 1))
            }
            _ => None,
        }
    }
    search(&value, 0)
}
